    // ============ Escrow Creation ============
    /**
     * @notice Create a new escrow transfer
     * @param token Token address (ERC20 for EscrowVault, address(this) for EscrowableERC20)
     * @param to Recipient address
     * @param amount Total amount to escrow (fee deducted). Must be >= MIN_ESCROW_AMOUNT (1000 wei)
     * @param settings Escrow configuration (resolver, yield, auto-times, etc.)
     * @return workflowId The workflow ID (array index)
     * @dev Fee deducted from amount. Overflow protection in Solidity 0.8+.
     */
    function createEscrow(
        address token,
        address to,
        uint256 amount,
        EscrowSettings memory settings
    ) public nonReentrant whenNotPaused returns (uint256) {
        uint256 workflowId = escrowTransfers.length; // Array index IS the workflowId

        // CreateOps is mandatory (removed inline fallback to save >1KB bytecode)
        if (address(createOps) == address(0)) revert ZeroCreateOps();
        IResolutionModule resolutionModule = _getResolutionModule(workflowId);
        CreateOps.CreateResult memory result = createOps.computeEscrowCreation(
            token,
            to,
            _msgSender(),
            amount,
            settings,
            escrowFee,
            workflowId,
            address(resolutionModule)
        );

        // Pull tokens (state modification - must stay in BaseEscrow)
        _pullTokens(token, _msgSender(), amount);

        // Store escrow struct (state modification - must stay in BaseEscrow)
        escrowTransfers.push(
            EscrowTransfer({
                token: token,
                to: to,
                from: _msgSender(),
                amountAfterFee: result.amountAfterFee,
                escrowState: EscrowState.PENDING,
                senderStatus: SenderStatus.NONE,
                recipientStatus: RecipientStatus.NONE,
                disputeResolver: result.resolver,
                autoReleaseTime: 0, // Set by _applyEscrowSettings
                autoCancelTime: 0   // Set by _applyEscrowSettings
            })
        );

        // Update accounting (state modification - must stay in BaseEscrow)
        _updateEscrowBalance(token, result.amountAfterFee, true);
        _recordFee(token, result.fee);

        // Apply settings and snapshot modules (state modification - must stay in BaseEscrow)
        _applyEscrowSettings(workflowId, settings);
        _snapshotModulesForEscrow(workflowId);

        // Yield deposit (optional, non-blocking)
        if (result.yieldEnabled && result.shouldDepositYield) {
            IYieldGenerationModule genModule = _getYieldGenerationModule(workflowId);
            if (address(genModule) != address(0) && genModule.isTokenSupported(token)) {
                // Use low-level call to save bytecode
                (bool success, ) = address(genModule).call(
                    abi.encodeWithSelector(IYieldGenerationModule.depositForYield.selector, workflowId, token, result.amountAfterFee)
                );
                if (!success) {
                    emit YieldHandlingFailed(workflowId, token, result.amountAfterFee, uint8(FailureReason.DEPOSIT_FAILED));
                    emit OperationFailure(
                        1,
                        workflowId,
                        address(genModule),
                        IYieldGenerationModule.depositForYield.selector,
                        uint8(FailureReason.DEPOSIT_FAILED)
                    );
                }
            }
        }

        // Emit events (state modification - must stay in BaseEscrow)
        emit EscrowCreated(workflowId, token, _msgSender(), to, amount, result.amountAfterFee, result.fee);
        emit EscrowStateChanged(workflowId, EscrowState.NONE, EscrowState.PENDING);
        _emitEscrowTransferCreated(workflowId, token, _msgSender(), to, amount);

        return workflowId;
    }

    function _pullTokens(address token, address from, uint256 amount) internal virtual;
    function _recordFee(address token, uint256 amount) internal virtual;
    function _depositForYield(
        IYieldGenerationModule genModule,
        uint256 workflowId,
        address token,
        uint256 amount
    ) internal virtual;
    function _emitEscrowTransferCreated(
        uint256 workflowId,
        address token,
        address from,
        address to,
        uint256 amount
    ) internal virtual;

    function _snapshotModulesForEscrow(uint256 workflowId) internal {
        address resModule = address(_getResolutionModule(workflowId));
        address relStrat = address(_getReleaseStrategy(workflowId));
        address genMod = address(_getYieldGenerationModule(workflowId));
        address distMod = address(_getYieldDistributionModule(workflowId));

        // PRIORITY 3: Snapshot incentive module at creation to avoid dynamic discovery
        address incentiveMod = address(0);
        if (resModule != address(0)) {
            // Try to read incentiveModule from resolution module (if supported)
            (bool success, bytes memory data) = resModule.staticcall(
                abi.encodeWithSelector(SEL_INCENTIVE_MODULE)
            );
            if (success && data.length >= 32) {
                incentiveMod = abi.decode(data, (address));
            }
        }

        // Snapshot modules and fees at creation time (immutable for this escrow)
        moduleSnapshots[workflowId] = ModuleSnapshot({
            resolutionModule: resModule,
            releaseStrategy: relStrat,
            yieldGenerationModule: genMod,
            yieldDistributionModule: distMod,
            incentiveModule: incentiveMod,
            yieldProtocolFeeBps: yieldProtocolFeeBps,
            appealBondProtocolFeeBps: appealBondProtocolFeeBps
        });

        // Module snapshot and fee data now included in EscrowCreated event
        // No separate events needed
    }

    // ============ Escrow Actions ============
    /**
     * @notice Automatically execute timed actions (auto-release or auto-cancel)
     * @param workflowId The escrow ID
     * @return executed Whether an action was executed
     * @dev Checks if auto-release or auto-cancel time has passed and executes if so.
     *      Can be called by anyone to trigger automatic actions.
     */
    function automateTimedActions(uint256 workflowId) external nonReentrant returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        PendingSettlement storage pending = pendingSettlements[workflowId];

        if (address(settlementOps) == address(0)) return false;

        // Use SettlementOps to compute timed actions
        // Convert storage to memory struct for external call
        SettlementOps.SettlementPendingSettlement memory pendingMem = SettlementOps.SettlementPendingSettlement({
            exists: pending.exists,
            isRelease: pending.isRelease,
            appealDeadline: pending.appealDeadline,
            resolutionHash: pending.resolutionHash
        });
        (uint8 actionType, bool isRelease) = settlementOps.computeTimedActions(
            workflowId,
            et,
            pendingMem,
            timeoutConfig
        );

        if (actionType == 0) return false;

        if (actionType == 3) {
            // Pending settlement execution
            delete pendingSettlements[workflowId];

            // Optionally finalize dispute in resolution module
            IResolutionModule resolutionModule = _getResolutionModule(workflowId);
            if (address(resolutionModule) != address(0)) {
                (bool success, ) = address(resolutionModule).call(
                    abi.encodeWithSelector(SEL_FINALIZE_DISPUTE, workflowId)
                );
                success; // Ignore failure
            }

            // Execute the settlement
            if (isRelease) {
                _releaseEscrowTransfer(workflowId);
            } else {
                _cancelAndRefund(workflowId);
            }

            emit PendingSettlementExecuted(workflowId, isRelease);
            emit EscrowTransferAutoResult(
                workflowId,
                isRelease ? et.to : et.from,
                et.token,
                et.amountAfterFee,
                true,
                3
            );
            return true;
        } else if (actionType == 1) {
            // Auto-release
            _releaseEscrowTransfer(workflowId);
            emit EscrowTransferAutoResult(workflowId, et.to, et.token, et.amountAfterFee, true, 1);
            return true;
        } else if (actionType == 2) {
            // Auto-cancel
            _cancelAndRefund(workflowId);
            emit EscrowTransferAutoResult(workflowId, et.from, et.token, et.amountAfterFee, true, 2);
            return true;
        }

        return false;
    }

    function _cancelWorkflow(uint256 id, address caller, bool isSender) internal returns (bool) {
        EscrowTransfer storage et = escrowTransfers[id];
        if (isSender) et.senderStatus = SenderStatus.AGREE_TO_CANCEL;
        else et.recipientStatus = RecipientStatus.AGREE_TO_CANCEL;
        emit CancelRequested(id, caller);
        if (
            et.senderStatus == SenderStatus.AGREE_TO_CANCEL &&
            et.recipientStatus == RecipientStatus.AGREE_TO_CANCEL
        ) {
            emit CancelConfirmed(id, caller);
            _cancelAndRefund(id);
        }
        return true;
    }

    /**
     * @notice Recipient requests to cancel the escrow
     * @param workflowId The escrow ID
     * @return success Whether the cancel request was processed
     */
    function recipientCancel(uint256 workflowId) external returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (et.to != _msgSender()) revert NotRecipient(workflowId, _msgSender(), et.to);
        if (et.escrowState != EscrowState.PENDING)
            revert TransferNotPending(workflowId, et.escrowState);
        return _cancelWorkflow(workflowId, _msgSender(), false);
    }

    /**
     * @notice Sender requests to cancel the escrow
     * @param workflowId The escrow ID
     * @return success Whether the cancel request was processed
     */
    function senderCancel(uint256 workflowId) external returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (et.from != _msgSender()) revert NotSender(workflowId, _msgSender(), et.from);
        if (et.escrowState != EscrowState.PENDING)
            revert TransferNotPending(workflowId, et.escrowState);
        return _cancelWorkflow(workflowId, _msgSender(), true);
    }

    // ============ Dispute Management ============
    /**
     * @notice Automatically cancel a disputed escrow that has timed out
     * @param workflowId The escrow ID
     * @return success Whether the auto-cancel was executed
     * @dev Can be called by anyone once maxDisputeDuration has passed.
     *      Refunds the full amount to the sender.
     */
    function autoCancelDisputedEscrow(uint256 workflowId) external nonReentrant returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (et.escrowState != EscrowState.DISPUTED) {
            revert TransferNotInDispute(workflowId, et.escrowState);
        }
        uint256 ts = disputeRaisedTimestamp[workflowId];
        if (ts == 0 || block.timestamp < ts + timeoutConfig.maxDisputeDuration) {
            revert InvalidState(workflowId, uint8(EscrowState.DISPUTED), uint8(et.escrowState)); // Dispute timeout not exceeded
        }
        address from = et.from;
        uint256 amt = et.amountAfterFee;
        _cancelAndRefund(workflowId);
        et.escrowState = EscrowState.RESOLVED;
        delete disputeRaisedTimestamp[workflowId];
        emit EscrowStateChanged(workflowId, EscrowState.DISPUTED, EscrowState.RESOLVED);
        emit DisputeAutoCancelled(workflowId, from, amt, uint8(FailureReason.TIMEOUT));
        emit EscrowTransferResolved(workflowId, from, et.to, amt);
        return true;
    }

    // PRIORITY: Removed isDisputeTimedOut() - moved to EscrowViewContract to reduce contract size

    /**
     * @notice Raise a dispute for an escrow
     * @param workflowId The escrow ID
     * @return success Whether the dispute was raised successfully
     */
    function raiseDispute(uint256 workflowId) external returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (et.escrowState != EscrowState.PENDING)
            revert TransferNotPending(workflowId, et.escrowState);
        address disputeResolver = et.disputeResolver;
        bool isSender = (et.from == _msgSender());
        if (!isSender && et.to != _msgSender())
            revert NotParticipant(workflowId, _msgSender(), et.from, et.to);
        StateManagementLibrary.transitionToDisputed(et, workflowId, isSender);
        disputeRaisedTimestamp[workflowId] = block.timestamp;
        emit EscrowStateChanged(workflowId, EscrowState.PENDING, EscrowState.DISPUTED);
        emit DisputeOpened(workflowId, _msgSender(), disputeResolver);
        emit EscrowTransferDisputed(workflowId, et.from, et.to, et.amountAfterFee);
        address updated = DisputeInitializationLibrary.initializeInModule(
            address(_getResolutionModule(workflowId)),
            workflowId,
            disputeResolver,
            EscrowEncodingLibrary.encodeEscrowTransferData(
                et.token,
                et.from,
                et.to,
                et.amountAfterFee
            )
        );
        if (updated != disputeResolver) {
            et.disputeResolver = updated;
            disputeResolver = updated;
        }
        DisputeInitializationLibrary.callResolverCallback(disputeResolver, workflowId);

        // Call incentive module onDisputeOpened hook
        // PRIORITY 3: Use snapshotted incentive module (no dynamic discovery)
        address incentiveModAddr = moduleSnapshots[workflowId].incentiveModule;
        if (incentiveModAddr != address(0)) {
            IIncentiveModule incentiveMod = IIncentiveModule(incentiveModAddr);
            // Calculate escrow fee: fee = amount * escrowFee / ESCROW_FEE_DENOMINATOR
            // Original amount = amountAfterFee + fee, so: fee = (amountAfterFee * escrowFee) / (ESCROW_FEE_DENOMINATOR - escrowFee)
            uint256 originalAmount = et.amountAfterFee +
                ((et.amountAfterFee * escrowFee) / (ESCROW_FEE_DENOMINATOR - escrowFee));
            uint256 escrowFeeAmount = (originalAmount * escrowFee) / ESCROW_FEE_DENOMINATOR;
            // Use low-level call to save bytecode (replaces try/catch)
            (bool success, ) = address(incentiveMod).call(
                abi.encodeWithSelector(
                    IIncentiveModule.onDisputeOpened.selector,
                    workflowId,
                    et.token,
                    originalAmount,
                    escrowFeeAmount,
                    0
                )
            );
            if (!success) {
                // MED-3: Emit event for monitoring
                emit IncentiveModuleCallFailed(workflowId, IIncentiveModule.onDisputeOpened.selector, uint8(FailureReason.CALL_FAILED));
                emit OperationFailure(
                    3,
                    workflowId,
                    incentiveModAddr,
                    IIncentiveModule.onDisputeOpened.selector,
                    uint8(FailureReason.CALL_FAILED)
                );
            }
        }

        return true;
    }

    /**
     * @notice Helper function to get incentive module from resolution module
     * @dev Used to access public incentiveModule variable from DecentralizedResolutionModule
     */
    // PRIORITY 3: Removed _getIncentiveModuleFromResolution - now using snapshotted incentiveModule

    /**
     * @notice Validate and prepare escalation, canceling any pending settlement
     * @param workflowId The escrow ID
     * @return et EscrowTransfer storage reference
     * @return resolutionModule Resolution module for this escrow
     */
    function _validateAndPrepareEscalation(
        uint256 workflowId
    ) internal returns (EscrowTransfer storage et, IResolutionModule resolutionModule) {
        _validateWorkflowId(workflowId);
        et = escrowTransfers[workflowId];
        if (address(disputeOps) == address(0)) revert ZeroDisputeOps();
        resolutionModule = _getResolutionModule(workflowId);

        // Cancel pending settlement if exists (state change - must stay in BaseEscrow)
        if (pendingSettlements[workflowId].exists) {
            delete pendingSettlements[workflowId];
            emit PendingSettlementCancelled(workflowId);
        }
    }

    // DEPRECATED: _collectEscalationBond removed - use BondCollector instead


    /**
     * @notice Escalate a dispute to a higher resolution level
     * @param workflowId The escrow ID
     * @return success Whether escalation succeeded
     * @return newDisputeResolver Address of the new resolver
     * @return newLevel New escalation level
     */
    function escalateDispute(
        uint256 workflowId
    )
        external
        payable
        nonReentrant
        returns (bool success, address newDisputeResolver, uint8 newLevel)
    {
        (EscrowTransfer storage et, IResolutionModule resolutionModule) = _validateAndPrepareEscalation(workflowId);

        // Get escalation info via disputeOps (which calls canEscalate and executeEscalation)
        // Escalation now uses appeal bonds exclusively
        DisputeOps.EscalationResult memory result = disputeOps.computeEscalation(
            address(resolutionModule),
            workflowId,
            _msgSender(),
            et.from,
            et.to,
            et.token,
            et.amountAfterFee,
            et.escrowState
        );
        if (!result.success) revert EscalationNotAllowed();

        // Get required appeal bond from resolution module
        bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(
            et.token,
            et.from,
            et.to,
            et.amountAfterFee
        );
        (bool bondCheckSuccess, bytes memory bondData) = address(resolutionModule).staticcall(
            abi.encodeWithSelector(
                IResolutionModule.getRequiredAppealBond.selector,
                workflowId,
                result.currentLevel,
                escrowData
            )
        );

        if (!bondCheckSuccess || bondData.length < 64) {
            revert AppealBondQueryFailed(workflowId);
        }

        (uint256 bondAmount, address bondToken) = abi.decode(bondData, (uint256, address));

        // Enforce msg.value invariants (audit-grade clarity)
        if (bondToken == address(0)) {
            if (msg.value < bondAmount) {
                revert InvalidBondMsgValue(workflowId, bondAmount, msg.value);
            }
        } else {
            if (msg.value != 0) {
                revert UnexpectedETH(workflowId, msg.value);
            }
        }

        if (bondAmount > 0) {
            // Use snapshotted incentive module (no dynamic discovery)
            address incentiveModAddr = moduleSnapshots[workflowId].incentiveModule;
            if (incentiveModAddr != address(0)) {
                IIncentiveModule incentiveMod = IIncentiveModule(incentiveModAddr);
                uint256 snapshottedBondFee = moduleSnapshots[workflowId].appealBondProtocolFeeBps;

                // Collect protocol fee (if enabled) and record net bond amount.
                uint256 protocolFeeAmount = 0;
                uint256 bondToRecord = bondAmount;

                if (snapshottedBondFee > 0 && escrowFeeAddress != address(0)) {
                    protocolFeeAmount = (bondAmount * snapshottedBondFee) / 10000;
                    if (protocolFeeAmount > 0) {
                        bondToRecord = bondAmount - protocolFeeAmount;
                        emit ProtocolFeeCollected(
                            1,
                            workflowId,
                            bondToken,
                            bondAmount,
                            snapshottedBondFee,
                            protocolFeeAmount
                        );
                    }
                }

                if (bondToken == address(0)) {
                    // ETH bond: pay protocol fee, then record bond (must match msg.value rules in incentive module).
                    if (protocolFeeAmount > 0) {
                        (bool feeSuccess, ) = payable(escrowFeeAddress).call{value: protocolFeeAmount}('');
                        if (!feeSuccess) revert TransferFailed(1, bondToken, escrowFeeAddress, protocolFeeAmount);
                    }

                    // For ETH bonds, depositor MUST equal escalatedBy.
                    incentiveMod.recordAppealBond{value: bondToRecord}(
                        workflowId,
                        _msgSender(), // depositor
                        _msgSender(), // escalatedBy
                        bondToRecord,
                        bondToken,
                        result.newLevel
                    );
                } else {
                    // ERC20 bond: custody lives in BondCollector, but recordAppealBond must be called
                    // by the escrow contract (onlyEscrowContract in incentive module).
                    if (address(bondCollector) == address(0)) revert ZeroBondCollector();

                    // Pull full bond amount into escrow contract, then fan out fee + custody transfer.
                    _pullTokens(bondToken, _msgSender(), bondAmount);
                    if (protocolFeeAmount > 0) {
                        IERC20(bondToken).safeTransfer(escrowFeeAddress, protocolFeeAmount);
                    }
                    IERC20(bondToken).safeTransfer(address(bondCollector), bondToRecord);

                    // Let incentive module pull tokens from BondCollector.
                    bondCollector.approveBondSpender(bondToken, address(incentiveMod), bondToRecord);
                    incentiveMod.recordAppealBond(
                        workflowId,
                        address(bondCollector), // depositor (custodian)
                        _msgSender(), // escalatedBy
                        bondToRecord,
                        bondToken,
                        result.newLevel
                    );
                    bondCollector.resetBondSpender(bondToken, address(incentiveMod));
                }
            }
        }

        // computeEscalation already called executeEscalation internally and succeeded
        // Use the result from computeEscalation instead of calling again
        address newResolver = result.newResolver;
        uint8 newLevel_ = result.newLevel;

        // Update escrow state with new resolver
        et.disputeResolver = newResolver;

        // Refund excess ETH if bond was ETH and msg.value exceeded bond amount
        if (bondToken == address(0) && msg.value > bondAmount) {
            uint256 excess = msg.value - bondAmount;
            if (excess > 0) {
                (bool s, ) = payable(_msgSender()).call{value: excess}('');
                if (!s) revert ExcessRefundTransferFailed(workflowId, _msgSender(), excess);
            }
        }
        emit DisputeEscalated(
            workflowId,
            result.currentLevel,
            newLevel_,
            newResolver,
            _msgSender()
        );
        return (true, newResolver, newLevel_);
    }

    // ============ Resolution ============
    /**
     * @notice Shared internal function for executing resolution actions (always full resolution)
     * @param workflowId The escrow workflow ID
     * @param isRelease True to release to recipient, false to cancel/refund to sender
     * @param resolutionHash Hash of resolution details (for offchain verification)
     * @return success True if resolution executed successfully
     */
    function _executeResolution(
        uint256 workflowId,
        bool isRelease,
        bytes32 resolutionHash
    ) internal returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];

        // Authorization check
        if (!_isAuthorizedDisputeResolver(workflowId, _msgSender()))
            revert NotAuthorizedResolver(_msgSender(), et.disputeResolver);

        // State check
        if (et.escrowState != EscrowState.DISPUTED)
            revert TransferNotInDispute(workflowId, et.escrowState);

        // Record resolution first (sets appeal deadline in module)
        // Note: Always use et.amountAfterFee (full resolution only) - used in _releaseEscrowTransfer/_cancelAndRefund
        _recordResolutionOutcome(workflowId, _msgSender(), isRelease, resolutionHash);
        emit EscrowResolved(workflowId, _msgSender(), resolutionHash);

        // Use SettlementOps to compute resolution execution parameters
        IResolutionModule resolutionModule = _getResolutionModule(workflowId);

        // Validate resolution module matches snapshot before execution
        address snap = moduleSnapshots[workflowId].resolutionModule;
        if (snap != address(0) && address(resolutionModule) != snap) {
            // Module has changed - use snapshotted module instead
            resolutionModule = IResolutionModule(snap);
        }

        // Validate module is still a valid contract before calling
        if (address(resolutionModule) != address(0)) {
            if (address(resolutionModule).code.length == 0) {
                revert NotAContract(1, address(resolutionModule)); // 1 = resolutionModule
            }
        }

        if (address(settlementOps) == address(0)) {
            // Fallback if SettlementOps not set
            revert ZeroSettlementOps();
        }

        SettlementOps.ResolutionResult memory result = settlementOps.computeResolutionExecution(
            address(resolutionModule),
            workflowId,
            isRelease,
            timeoutConfig
        );

        // If final round (MAX_ROUND), execute immediately (no appeal window)
        if (result.shouldExecute) {
            // Execute immediately - no appeal window for final round
            if (isRelease) {
                _releaseEscrowTransfer(workflowId);
            } else {
                _cancelAndRefund(workflowId);
            }
            return true;
        }

        // Store pending settlement (appeal window enforcement)
        // Transfer will be executed after appeal window expires via executePendingSettlement()
        pendingSettlements[workflowId] = PendingSettlement({
            exists: true,
            isRelease: isRelease,
            appealDeadline: result.appealDeadline,
            resolutionHash: resolutionHash
        });

        // Keep state as DISPUTED (not RESOLVED yet - will be finalized after appeal window)
        emit PendingSettlementSet(workflowId, isRelease, result.appealDeadline);

        return true;
    }

    /**
     * @notice Execute pending settlement after appeal window expires
     * @param workflowId The escrow workflow ID
     * @dev Can be called by anyone once appeal window has expired
     *      Executes the pending release or cancel that was stored during resolution
     *      Optionally finalizes the dispute in the resolution module if not already finalized
     */
    function executePendingSettlement(uint256 workflowId) external nonReentrant {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        PendingSettlement storage pending = pendingSettlements[workflowId];

        if (address(settlementOps) == address(0)) {
            revert ZeroSettlementOps();
        }

        // Use SettlementOps to compute pending settlement execution
        // Convert storage to memory struct for external call
        SettlementOps.SettlementPendingSettlement memory pendingMem = SettlementOps.SettlementPendingSettlement({
            exists: pending.exists,
            isRelease: pending.isRelease,
            appealDeadline: pending.appealDeadline,
            resolutionHash: pending.resolutionHash
        });
        (bool canExecute, bool isRelease) = settlementOps.computePendingSettlementExecution(
            workflowId,
            pendingMem,
            et.escrowState
        );

        if (!canExecute) {
            if (!pending.exists) revert NoPendingSettlement(workflowId);
            if (block.timestamp < pending.appealDeadline) {
                revert AppealWindowNotExpired(workflowId, pending.appealDeadline, block.timestamp);
            }
            revert NotInDisputedState(workflowId, et.escrowState);
        }

        // Clear pending settlement before execution (prevent reentrancy)
        delete pendingSettlements[workflowId];

        // Optionally finalize dispute in resolution module if supported
        // This ensures appeal bonds are distributed
        IResolutionModule resolutionModule = _getResolutionModule(workflowId);
        if (address(resolutionModule) != address(0)) {
            // Try to call finalizeDispute if it exists (DecentralizedResolutionModule)
            // This is a best-effort call - if it fails, we still execute the settlement
            (bool success, ) = address(resolutionModule).call(
                abi.encodeWithSelector(SEL_FINALIZE_DISPUTE, workflowId)
            );
            // Ignore failure - settlement will execute regardless
            success;
        }

        // Execute the settlement
        if (isRelease) {
            _releaseEscrowTransfer(workflowId);
        } else {
            _cancelAndRefund(workflowId);
        }

        emit PendingSettlementExecuted(workflowId, isRelease);
    }

    // PRIORITY: Removed getPendingSettlement - use public mapping getter pendingSettlements(workflowId) directly
    // EscrowViewContract calculates canExecute itself: block.timestamp >= appealDeadline

    /**
     * @notice Cancel dispute resolution - refund full amount to sender
     * @param workflowId The escrow workflow ID
     * @param resolutionHash Hash of resolution details (for offchain verification)
     * @return success True if resolution executed successfully
     */
    function cancelAsDisputeResolver(
        uint256 workflowId,
        bytes32 resolutionHash
    ) public nonReentrant returns (bool) {
        return _executeResolution(workflowId, false, resolutionHash);
    }

    /**
     * @notice Release dispute resolution - release full amount to recipient
     * @param workflowId The escrow workflow ID
     * @param resolutionHash Hash of resolution details (for offchain verification)
     * @return success True if resolution executed successfully
     */
    function releaseAsDisputeResolver(
        uint256 workflowId,
        bytes32 resolutionHash
    ) public nonReentrant returns (bool) {
        return _executeResolution(workflowId, true, resolutionHash);
    }

    function _isAuthorizedDisputeResolver(
        uint256 workflowId,
        address disputeResolver
    ) internal view returns (bool) {
        EscrowTransfer storage et = escrowTransfers[workflowId];
        address snap = moduleSnapshots[workflowId].resolutionModule;
        if (snap != address(0)) {
            // Use low-level staticcall instead of try-catch for gas efficiency
            bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(
                et.token,
                et.from,
                et.to,
                et.amountAfterFee
            );
            (bool success, bytes memory data) = snap.staticcall(
                abi.encodeWithSelector(
                    IResolutionModule.isAuthorizedDisputeResolver.selector,
                    workflowId,
                    disputeResolver,
                    escrowData
                )
            );
            if (success && data.length >= 64) {
                (bool authorized, ) = abi.decode(data, (bool, uint8));
                if (authorized) return true;
            }
        }
        return disputeResolver == et.disputeResolver;
    }

    function _getDisputeResolverForNewEscrow(
        uint256 workflowId,
        address token,
        address from,
        address to,
        uint256 amount
    ) internal view virtual returns (address) {
        IResolutionModule module = _getResolutionModule(workflowId);
        if (address(module) == address(0)) revert ResolutionModuleError(1); // code 1 = not configured

        // Use low-level staticcall instead of try-catch for gas efficiency
        bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(token, from, to, amount);
        (bool success, bytes memory data) = address(module).staticcall(
            abi.encodeWithSelector(
                IResolutionModule.getDisputeResolver.selector,
                workflowId,
                escrowData
            )
        );

        if (!success || data.length < 64) {
            revert ResolutionModuleError(2); // code 2 = call failed
        }

        (address disputeResolver, ) = abi.decode(data, (address, uint8));
        if (disputeResolver == address(0)) {
            revert ResolutionModuleError(3); // code 3 = returned zero address
        }
        return disputeResolver;
    }

    function _applyEscrowSettings(uint256 workflowId, EscrowSettings memory settings) internal {
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (settings.customResolver != address(0)) et.disputeResolver = settings.customResolver;
        bool def = (settings.autoReleaseTime == 0 && settings.autoCancelTime == 0);

        uint256 autoReleaseTime = settings.autoReleaseTime > 0
            ? settings.autoReleaseTime
            : (def ? timeoutConfig.defaultAutoReleaseTime : 0);
        if (autoReleaseTime > type(uint64).max) {
            revert InvalidAutoTime(AUTO_TIME_TOO_LARGE, autoReleaseTime, block.timestamp);
        }
        et.autoReleaseTime = uint64(autoReleaseTime);

        uint256 autoCancelTime = settings.autoCancelTime > 0
            ? settings.autoCancelTime
            : (def ? timeoutConfig.defaultAutoCancelTime : 0);
        if (autoCancelTime > type(uint64).max) {
            revert InvalidAutoTime(AUTO_TIME_TOO_LARGE, autoCancelTime, block.timestamp);
        }
        et.autoCancelTime = uint64(autoCancelTime);
        escrowSettings[workflowId] = settings;

        emit EscrowSettingsUpdated(workflowId, settings);
    }

    // ============ View Functions ============
    // PRIORITY: Removed explicit getter functions to reduce contract size (~1.5-2.3 KB saved)
    // Public storage variables provide free auto-generated getters:
    // - escrowTransfers(uint256) - public array getter
    // - claimableBalances(workflowId, user) - public mapping getter
    // - escrowSettings(workflowId) - public mapping getter
    // - pendingSettlements(workflowId) - public mapping getter
    // - timeoutConfig - public struct getter
    // EscrowViewContract uses these public storage getters directly

    // ============ Withdrawal ============
    /**
     * @notice Withdraw claimable escrow funds (pull model)
     * @param workflowId The escrow ID
     * @return amount Amount withdrawn
     */
    function withdrawEscrow(uint256 workflowId) external nonReentrant returns (uint256) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];

        // Verify escrow is finalized (or released/cancelled)
        if (et.escrowState != EscrowState.RESOLVED &&
            et.escrowState != EscrowState.RELEASED &&
            et.escrowState != EscrowState.REFUNDED) {
            revert TransferNotFinalized(workflowId, et.escrowState);
        }

        address token = et.token; // Single token per escrow
        uint256 amount = claimableBalances[workflowId][msg.sender];
        if (amount == 0) revert NoClaimableBalance(workflowId, msg.sender, token);

        // Idempotent: set to 0 before transfer (checks-effects-interactions)
        claimableBalances[workflowId][msg.sender] = 0;

        // Note: Balance already updated during finalization, don't double-subtract
        _transferTokens(token, msg.sender, amount);

        emit EscrowWithdrawn(workflowId, msg.sender, token, amount);
        return amount;
    }

    // ============ Recovery ============
    // PRIORITY 5: Removed recoverNativeETH
    // This function has been removed to reduce contract size.
    // For ERC20 vaults (EscrowVault), native ETH recovery is not needed.
    // If needed for ETH-specific vaults, it can be added to a separate RecoveryOps contract.

    /**
     * @notice Recover ERC20 tokens sent to the contract
     * @param token Token address to recover
     * @param recipient Address to receive the recovered tokens
     * @param amount Amount of tokens to recover
     * @return success Whether recovery succeeded
     * @dev Abstract function - derived contracts MUST override with accounting validation
     */
    function recoverERC20(
        address token,
        address recipient,
        uint256 amount
    ) external virtual onlyRole(ROLE_TIMELOCK) nonReentrant returns (bool) {
        /// @dev Base implementation - derived contracts MUST override with proper accounting checks
        ///      This prevents recovery of tokens that are held in escrow or fees
        uint256 rec = RecoveryLibrary.recoverERC20(
            token,
            recipient,
            amount,
            IERC20(token).balanceOf(address(this))
        );
        emit ERC20Recovered(token, recipient, rec);
        return true;
    }

    // ============ Internal Helpers ============
    function _validateWorkflowId(uint256 workflowId) internal view {
        if (workflowId >= escrowTransfers.length) {
            revert InvalidWorkflowId(workflowId, escrowTransfers.length);
        }
    }

    function _requirePending(uint256 workflowId) internal view {
        _validateWorkflowId(workflowId);
        EscrowState st = escrowTransfers[workflowId].escrowState;
        if (st != EscrowState.PENDING) {
            revert TransferNotPending(workflowId, st);
        }
    }

    function _validateEscrowSettings(EscrowSettings memory settings) internal view {
        SettingsValidationLibrary.validateEscrowSettings(settings, block.timestamp);
    }

    /**
     * @notice Attempt automatic transfer with graceful fallback to claimable balance
     * @param workflowId The escrow ID
     * @param recipient Address to receive funds
     * @param token Token address
     * @param amount Amount to transfer
     * @return transferred True if transfer succeeded, false if fell back to claimable
     */
    function _attemptAutoTransfer(
        uint256 workflowId,
        address recipient,
        address token,
        uint256 amount
    ) internal returns (bool transferred) {
        if (amount == 0) {
            return false;
        }

        // Attempt transfer using low-level call
        bool success = _tryTransfer(token, recipient, amount);
        if (success) {
            emit EscrowTransferAutoResult(workflowId, recipient, token, amount, true, 0);
            return true;
        } else {
            // Transfer failed - fallback to pull model
            claimableBalances[workflowId][recipient] += amount;
            emit ClaimableBalanceSet(workflowId, recipient, token, amount);
            emit EscrowTransferAutoResult(
                workflowId,
                recipient,
                token,
                amount,
                false,
                uint8(FailureReason.PUSH_FAILED_FALLBACK_TO_PULL)
            );
            emit OperationFailure(
                4,
                workflowId,
                token,
                IERC20.transfer.selector,
                uint8(FailureReason.PUSH_FAILED_FALLBACK_TO_PULL)
            );
            return false;
        }
    }

    /**
     * @notice Low-level transfer helper that returns success status
     * @param token Token address
     * @param to Recipient address
     * @param amount Amount to transfer
     * @return success Whether transfer succeeded
     */
    function _tryTransfer(address token, address to, uint256 amount) internal returns (bool success) {
        // Use low-level call to token's transfer function
        (success, ) = token.call(abi.encodeWithSelector(
            IERC20.transfer.selector,
            to,
            amount
        ));

        // Check return value (ERC20 standard: returns bool)
        if (success) {
            // Verify return data contains true
            assembly {
                if returndatasize() {
                    returndatacopy(0, 0, returndatasize())
                    success := and(mload(0), 0xff) // Check if first byte is non-zero
                }
            }
        }

        return success;
    }

    /**
     * @notice Handle yield withdrawal and distribution, returning actual amount available
     * @param workflowId The escrow ID
     * @param token Token address
     * @param amount Original escrow amount
     * @return actualAmount Actual amount available after yield handling (may include yield)
     */
    function _handleYieldAndGetActualAmount(
        uint256 workflowId,
        address token,
        uint256 amount
    ) internal returns (uint256 actualAmount) {
        actualAmount = amount;

        // P1: module wiring observability (only emit if yield is enabled for this escrow).
        EscrowSettings memory settings = escrowSettings[workflowId];
        bool yieldEnabled = settings.yieldPreset != YieldPreset.OFF;
        if (address(yieldOps) == address(0)) {
            if (yieldEnabled) {
                emit YieldHandlingFailed(workflowId, token, amount, uint8(FailureReason.MODULE_NOT_SET));
                emit OperationFailure(
                    2,
                    workflowId,
                    address(0),
                    YieldOps.handleYield.selector,
                    uint8(FailureReason.MODULE_NOT_SET)
                );
            }
            return actualAmount;
        }
        if (address(yieldOps).code.length == 0) {
            if (yieldEnabled) {
                emit YieldHandlingFailed(workflowId, token, amount, uint8(FailureReason.MODULE_NOT_CONTRACT));
                emit OperationFailure(
                    2,
                    workflowId,
                    address(yieldOps),
                    YieldOps.handleYield.selector,
                    uint8(FailureReason.MODULE_NOT_CONTRACT)
                );
            }
            return actualAmount;
        }

        IYieldGenerationModule genModule = _getYieldGenerationModule(workflowId);
        IYieldDistributionModule distModule = _getYieldDistributionModule(workflowId);

        // Use snapshotted fee (immutable per-escrow) instead of global fee
        uint256 snapshottedYieldFee = moduleSnapshots[workflowId].yieldProtocolFeeBps;

        // Derive distribution data from preset
        EscrowTransfer memory et = escrowTransfers[workflowId];
        bytes memory distributionData = YieldPresetLibrary.deriveDistributionData(
            settings.yieldPreset,
            et.from,  // sender (buyer)
            et.to     // recipient (seller)
        );

        // Low-level call to avoid try/catch bytecode bloat (yield is non-critical)
        (bool ok, bytes memory ret) = address(yieldOps).call(
            abi.encodeWithSelector(
                YieldOps.handleYield.selector,
                genModule,
                distModule,
                workflowId,
                token,
                amount,
                snapshottedYieldFee,
                escrowFeeAddress,
                distributionData
            )
        );

        if (!ok) {
            // For yield withdrawal paths, expose a stable "withdrawal failed" signal.
            emit YieldHandlingFailed(workflowId, token, amount, uint8(FailureReason.WITHDRAWAL_FAILED));
            emit OperationFailure(
                2,
                workflowId,
                address(yieldOps),
                YieldOps.handleYield.selector,
                uint8(FailureReason.CALL_FAILED)
            );
            return actualAmount;
        }
        // YieldOps currently returns YieldOps.YieldResult (4 * 32-byte words).
        // Guard decode so yield remains strictly non-blocking even if ABI drifts.
        if (ret.length < 128) {
            // For yield withdrawal paths, expose a stable "withdrawal failed" signal.
            emit YieldHandlingFailed(workflowId, token, amount, uint8(FailureReason.WITHDRAWAL_FAILED));
            emit OperationFailure(
                2,
                workflowId,
                address(yieldOps),
                YieldOps.handleYield.selector,
                uint8(FailureReason.MALFORMED_RETURN_DATA)
            );
            return actualAmount;
        }

        YieldOps.YieldResult memory result = abi.decode(ret, (YieldOps.YieldResult));

        // Use actual withdrawn amount (may include yield)
        // Yield is optional and non-critical - if withdrawal returns unexpected amount,
        // treat yield as failed and proceed with principal amount
        if (result.actualAmount > 0) {
            // Basic sanity check: actual amount should be >= principal (no loss)
            if (result.actualAmount < amount) {
                emit YieldHandlingFailed(workflowId, token, amount, uint8(FailureReason.LESS_THAN_PRINCIPAL));
                emit OperationFailure(
                    2,
                    workflowId,
                    address(yieldOps),
                    YieldOps.handleYield.selector,
                    uint8(FailureReason.LESS_THAN_PRINCIPAL)
                );
                actualAmount = amount; // Use principal amount
            } else {
                actualAmount = result.actualAmount; // Use actual amount (may include yield)
            }
        }

        return actualAmount;
    }

    function _cancelAndRefund(uint256 workflowId) internal {
        EscrowTransfer storage et = escrowTransfers[workflowId];
        uint256 amount = et.amountAfterFee;
        address from = et.from;
        address token = et.token;
        EscrowState oldStatus = StateManagementLibrary.transitionToRefunded(et, workflowId);
        emit EscrowStateChanged(workflowId, oldStatus, EscrowState.REFUNDED);

        // CRIT-1/HIGH-4: Use actual withdrawn amount from yield handling for accounting
        uint256 actualAmount = _handleYieldAndGetActualAmount(workflowId, token, amount);

        // Update accounting based on actual amount (CRIT-1 fix)
        _updateEscrowBalance(token, actualAmount, false);

        // Auto-transfer: Attempt automatic transfer, fallback to claimable if fails
        _attemptAutoTransfer(workflowId, from, token, actualAmount);
        _emitEscrowTransferCancelled(workflowId, token, from, amount);
    }

    function _releaseEscrowTransfer(uint256 workflowId) internal {
        EscrowTransfer storage et = escrowTransfers[workflowId];
        uint256 amount = et.amountAfterFee;
        address to = et.to;
        address token = et.token;
        EscrowState oldStatus = StateManagementLibrary.transitionToReleased(et, workflowId);
        emit EscrowStateChanged(workflowId, oldStatus, EscrowState.RELEASED);

        // CRIT-1/HIGH-4: Use actual withdrawn amount from yield handling for accounting
        uint256 actualAmount = _handleYieldAndGetActualAmount(workflowId, token, amount);

        // Update accounting based on actual amount (CRIT-1 fix)
        _updateEscrowBalance(token, actualAmount, false);

        // Auto-transfer: Attempt automatic transfer, fallback to claimable if fails
        _attemptAutoTransfer(workflowId, to, token, actualAmount);
        _emitEscrowTransferReleased(workflowId, token, to, amount);
    }

    function _transferTokens(address token, address to, uint256 amount) internal virtual;
    function _updateEscrowBalance(address token, uint256 amount, bool add) internal virtual;
    function _emitEscrowTransferCancelled(
        uint256 workflowId,
        address token,
        address from,
        uint256 amount
    ) internal virtual;
    function _emitEscrowTransferReleased(
        uint256 workflowId,
        address token,
        address to,
        uint256 amount
    ) internal virtual;
    function _getYieldGenerationModule(
        uint256 workflowId
    ) internal view virtual returns (IYieldGenerationModule);
    function _getYieldDistributionModule(
        uint256 workflowId
    ) internal view virtual returns (IYieldDistributionModule);
    function _getReleaseStrategy(
        uint256 workflowId
    ) internal view virtual returns (IReleaseStrategy);
    function _getResolutionModule(
        uint256 workflowId
    ) internal view virtual returns (IResolutionModule) {
        // BaseEscrow: return snapshotted module if exists, otherwise base-level module
        address snap = moduleSnapshots[workflowId].resolutionModule;
        if (snap != address(0)) {
            return IResolutionModule(snap);
        }
        return IResolutionModule(disputeResolutionModule);
    }

    // Resolution outcome enum (matches DecentralizedResolverStructs.ResolutionOutcome)
    enum ResolutionOutcome {
        NONE, // 0 - No resolution yet
        RELEASE, // 1 - Funds released to recipient
        CANCEL // 2 - Funds refunded to sender
    }

    function _recordResolutionOutcome(
        uint256 workflowId,
        address disputeResolver,
        bool isRelease,
        bytes32 /* resolutionHash */
    ) internal {
        address module = address(_getResolutionModule(workflowId));
        if (module == address(0)) return;
        // Note: resolutionHash is available via EscrowResolved event if modules need it
        // Current module interface doesn't include it, but can be added in future versions
        ResolutionOutcome outcome = isRelease
            ? ResolutionOutcome.RELEASE
            : ResolutionOutcome.CANCEL;
        uint256 resolutionTime = block.timestamp;
        (bool success, ) = module.call(
            abi.encodeWithSelector(
                SEL_RECORD_RESOLUTION,
                workflowId,
                disputeResolver,
                uint8(outcome),
                resolutionTime
            )
        );
        success;
    }
}

contracts/core/BondCollector.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts/access/AccessControl.sol';
import '../decentralized-resolution-module/IIncentiveModule.sol';
import '../types/EscrowTypes.sol';

/**
 * @title BondCollector
 * @notice External contract for collecting escalation bonds (ETH or ERC20)
 * @dev Extracted from BaseEscrow to reduce contract size (Priority 2 optimization)
 * 
 *      Handles:
 *      - ETH bond collection with protocol fee deduction
 *      - ERC20 bond collection with protocol fee deduction
 *      - Custody lives in this contract for ERC20 bonds (escrow transfers in, this contract approves incentive module)
 *      - Protocol fee transfer to fee address
 *      - Bond recording via incentive module
 */
contract BondCollector is AccessControl {
    using SafeERC20 for IERC20;

    // ============ Role Constants ============
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    // ============ Custom Errors ============
    error ZeroOwner();

    // Events
    event ProtocolFeeCollected(
        uint8 indexed kind, // 1 = appeal bond
        uint256 indexed workflowId,
        address indexed token,
        uint256 bondAmount,
        uint256 feeBps,
        uint256 feeAmount
    );

    /**
     * @notice Constructor for BondCollector
     * @param initialOwner Address that will receive DEFAULT_ADMIN_ROLE (for initial setup only)
     */
    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert ZeroOwner();
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialOwner must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialOwner);
    }

    /**
     * @notice Register an escrow contract (grants it ROLE_ESCROW_CONTRACT)
     * @param escrowContract Address of the escrow contract
     * @dev Only ROLE_TIMELOCK can register escrow contracts (governance-controlled)
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidAddress(ADDR_ESCROW_CONTRACT, escrowContract);
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    /**
     * @notice Collect escalation bond (ETH or ERC20) and deduct protocol fee
     * @param workflowId The escrow ID
     * @param incentiveMod Incentive module for bond recording
     * @param bondAmount Bond amount to collect
     * @param bondToken Bond token address (address(0) for ETH)
     * @param newLevel New escalation level
     * @param snapshottedBondFee Protocol fee in basis points (from module snapshot)
     * @param escrowFeeAddress Address to receive protocol fees
     * @param depositor Address that deposited the bond (user for ETH, this contract for ERC20)
     * @param escalatedBy Address that initiated the escalation (always the user)
     * @return collected Whether bond was successfully collected
     * @dev Only authorized escrow contracts can call this function
     */
    function collectBond(
        uint256 workflowId,
        IIncentiveModule incentiveMod,
        uint256 bondAmount,
        address bondToken,
        uint8 newLevel,
        uint256 snapshottedBondFee,
        address escrowFeeAddress,
        address depositor,
        address escalatedBy
    ) external payable onlyRole(ROLE_ESCROW_CONTRACT) returns (bool collected) {
        if (address(incentiveMod) == address(0)) return false;

        if (bondToken == address(0)) {
            // ETH bond
            uint256 ethToSend = bondAmount;
            if (msg.value > bondAmount) {
                ethToSend = bondAmount;
            }

            uint256 protocolFeeAmount = 0;
            if (snapshottedBondFee > 0 && escrowFeeAddress != address(0)) {
                protocolFeeAmount = (ethToSend * snapshottedBondFee) / 10000;
                if (protocolFeeAmount > 0) {
                    // Transfer protocol fee first - if it fails, revert to keep accounting clean
                    (bool feeSuccess, ) = payable(escrowFeeAddress).call{value: protocolFeeAmount}('');
                    if (!feeSuccess) {
                        return false; // Fee transfer failed
                    }
                    ethToSend = ethToSend - protocolFeeAmount;
                    emit ProtocolFeeCollected(1, workflowId, bondToken, bondAmount, snapshottedBondFee, protocolFeeAmount);
                }
            }

            if (ethToSend > 0) {
                // ETH bond: call payable function with ETH value
                // For ETH bonds, depositor = escalatedBy = user
                (bool s, ) = address(incentiveMod).call{value: ethToSend}(
                    abi.encodeWithSelector(
                        IIncentiveModule.recordAppealBond.selector,
                        workflowId,
                        depositor, // depositor (user for ETH)
                        escalatedBy, // escalatedBy (user)
                        ethToSend,
                        bondToken,
                        newLevel
                    )
                );
                return s;
            }
        } else {
            // ERC20 bond - custody is held by this contract
            // BaseEscrow transfers tokens to this contract before calling collectBond
            // Step 1: Calculate and transfer protocol fee
            uint256 protocolFeeAmount = 0;
            uint256 bondToRecord = bondAmount;

            if (snapshottedBondFee > 0 && escrowFeeAddress != address(0)) {
                protocolFeeAmount = (bondAmount * snapshottedBondFee) / 10000;
                if (protocolFeeAmount > 0) {
                    bondToRecord = bondAmount - protocolFeeAmount;
                    IERC20(bondToken).safeTransfer(escrowFeeAddress, protocolFeeAmount);
                    emit ProtocolFeeCollected(1, workflowId, bondToken, bondAmount, snapshottedBondFee, protocolFeeAmount);
                }
            }

            // Step 2: Approve incentive module to pull remaining tokens
            if (bondToRecord > 0) {
                // Pull-based pattern: approve incentive module to pull tokens
                // If recordAppealBond fails, tokens remain with this contract (no loss)
                IERC20(bondToken).safeIncreaseAllowance(address(incentiveMod), bondToRecord);
                try incentiveMod.recordAppealBond(workflowId, depositor, escalatedBy, bondToRecord, bondToken, newLevel) {
                    // Reset approval to zero after successful call
                    IERC20(bondToken).approve(address(incentiveMod), 0);
                    return true;
                } catch {
                    // Reset approval on failure
                    IERC20(bondToken).approve(address(incentiveMod), 0);
                    return false;
                }
            }
        }
        return false;
    }

    /**
     * @notice Approve a spender to pull ERC20 bond tokens
     * @dev Intended for escrow contract flows where the escrow contract calls the incentive module,
     *      but custody lives in this contract (BondCollector).
     */
    function approveBondSpender(
        address token,
        address spender,
        uint256 amount
    ) external onlyRole(ROLE_ESCROW_CONTRACT) {
        IERC20(token).safeIncreaseAllowance(spender, amount);
    }

    /**
     * @notice Reset an ERC20 approval back to zero
     * @dev Best practice to avoid leaving allowances lingering on third-party contracts.
     */
    function resetBondSpender(address token, address spender) external onlyRole(ROLE_ESCROW_CONTRACT) {
        IERC20(token).approve(spender, 0);
    }
}

contracts/core/EscrowableERC20.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/token/ERC20/ERC20.sol';
import './BaseEscrow.sol';
import '../types/EscrowTypes.sol';
import '../interfaces/IReleaseStrategy.sol';
import '../shared/interfaces/IResolutionModule.sol';
import '../interfaces/IYieldGenerationModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
import '../interfaces/IModuleRegistry.sol';
import '../libraries/RecoveryLibrary.sol';

/**
 * @title EscrowableERC20
 * @notice ERC20 token with built-in escrow functionality
 * @dev Extends ERC20 and BaseEscrow to provide escrow capabilities for the token itself.
 *      Users can create escrows using this contract's tokens, with support for disputes,
 *      attachments, yield generation via Aave, and modular release/resolution strategies.
 *      Token parameter is always address(this) - single token escrow contract.
 */
contract EscrowableERC20 is ERC20, BaseEscrow {
    uint256 public constant INITIAL_SUPPLY = 1000000000000000000000000; // 1,000,000 tokens with 18 decimals

    /// @notice Default yield protocol fee (30%)
    uint256 public constant DEFAULT_YIELD_PROTOCOL_FEE_BPS = 3000; // 30% default

    // Single token tracking (not per-token like EscrowVault)
    uint256 public totalHeldInEscrow = 0;
    uint256 public totalFees = 0;

    // Default module instances
    IReleaseStrategy public defaultReleaseStrategy;
    IResolutionModule public defaultDisputeResolutionModule;
    IYieldGenerationModule public defaultYieldGenerationModule;
    IYieldDistributionModule public defaultYieldDistributionModule;

    // Module registry for validation (optional - if not set, validation skipped)
    IModuleRegistry public moduleRegistry;

    // Events specific to EscrowableERC20 (without token parameter since token is always address(this))
    event EscrowTransferCreated(uint256 indexed workflowId, address indexed from, address indexed to, uint256 amount);
    event EscrowTransferReleased(uint256 indexed workflowId, address indexed to, uint256 amount);
    event EscrowTransferCancelled(uint256 indexed workflowId, address indexed from, uint256 amount);
    event FeesWithdrawn(uint256 amount);

    // Module events
    event DefaultReleaseStrategyQueued(address indexed oldStrategy, address indexed newStrategy, uint64 eta);
    event DefaultReleaseStrategyActivated(address indexed oldStrategy, address indexed newStrategy);
    event DefaultResolutionModuleQueued(address indexed oldModule, address indexed newModule, uint64 eta);
    event DefaultResolutionModuleActivated(address indexed oldModule, address indexed newModule);
    event DefaultYieldGenerationModuleQueued(address indexed oldModule, address indexed newModule, uint64 eta);
    event DefaultYieldGenerationModuleActivated(address indexed oldModule, address indexed newModule);
    event DefaultYieldDistributionModuleQueued(address indexed oldModule, address indexed newModule, uint64 eta);
    event DefaultYieldDistributionModuleActivated(address indexed oldModule, address indexed newModule);

    /// @dev Legacy slow-lane functions are disabled; use ModuleSnapshotRegistry.
    error UseModuleSnapshotRegistry();

    constructor(
        string memory name,
        string memory symbol,
        uint256 escrowFeeBps,
        address feeAddress,
        address yieldOpsAddress,
        address disputeOpsAddress
    ) ERC20(name, symbol) {
        // Validate escrow fee is within allowed range (0 to 2%)
        if (escrowFeeBps > MAX_ESCROW_FEE_BPS) {
            revert InvalidEscrowFee(escrowFeeBps, MAX_ESCROW_FEE_BPS);
        }
        if (feeAddress == address(0)) revert InvalidAddress(ADDR_FEE_RECIPIENT, feeAddress);
        if (yieldOpsAddress == address(0)) revert InvalidAddress(ADDR_YIELD_OPS, yieldOpsAddress);
        if (disputeOpsAddress == address(0)) revert InvalidAddress(ADDR_DISPUTE_OPS, disputeOpsAddress);

        escrowFee = escrowFeeBps;
        escrowFeeAddress = feeAddress;
        yieldOps = YieldOps(yieldOpsAddress);
        disputeOps = DisputeOps(disputeOpsAddress);

        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(ROLE_TIMELOCK, _msgSender());

        // Initialize protocol fees with validation
        uint256 initialYieldFee = DEFAULT_YIELD_PROTOCOL_FEE_BPS;
        uint256 initialAppealFee = 0; // 0% default

        if (initialYieldFee > MAX_PROTOCOL_FEE_BPS) {
            revert FeeExceedsMaximum(initialYieldFee, MAX_PROTOCOL_FEE_BPS);
        }
        if (initialAppealFee > MAX_PROTOCOL_FEE_BPS) {
            revert FeeExceedsMaximum(initialAppealFee, MAX_PROTOCOL_FEE_BPS);
        }

        yieldProtocolFeeBps = initialYieldFee;
        appealBondProtocolFeeBps = initialAppealFee;

        // Initialize timeout config
        timeoutConfig = TimeoutConfig({
            defaultAutoReleaseTime: 0,
            defaultAutoCancelTime: 0,
            maxDisputeDuration: 90 days,
            appealWindowDuration: 2 days
        });

        // Mint initial supply to deployer
        _mint(_msgSender(), INITIAL_SUPPLY);
    }

    // ============ Convenience Functions ============

    /**
     * @notice Create a new escrow with default settings
     * @param seller Recipient address (seller)
     * @param amount Amount to escrow (fee will be deducted)
     * @return workflowId The ID of the created escrow transfer
     * @dev Convenience function - calls BaseEscrow.createEscrow with address(this) as token
     */
    function createEscrow(address seller, uint256 amount) public whenNotPaused returns (uint256) {
        return createEscrow(address(this), seller, amount, SettingsValidationLibrary.getDefaultSettings());
    }

    /**
     * @notice Create an escrow with custom auto-release or auto-cancel time
     * @param seller Recipient address (seller)
     * @param amount Amount to escrow (after fee deduction)
     * @param autoReleaseTime Timestamp for automatic release (0 = no auto-release)
     * @param autoCancelTime Timestamp for automatic cancel (0 = no auto-cancel)
     * @return workflowId The ID of the created escrow transfer
     * @dev Convenience function - calls BaseEscrow.createEscrow with timing settings
     */
    function createEscrow(
        address seller,
        uint256 amount,
        uint256 autoReleaseTime,
        uint256 autoCancelTime
    ) public whenNotPaused returns (uint256) {
        EscrowSettings memory settings = SettingsValidationLibrary.getDefaultSettings();
        settings.autoReleaseTime = autoReleaseTime;
        settings.autoCancelTime = autoCancelTime;
        return createEscrow(address(this), seller, amount, settings);
    }

    // ============ BaseEscrow Hook Implementations ============

    /**
     * @dev Transfer tokens from sender to contract using ERC20's internal _transfer
     * @param token Token address (must be address(this) for EscrowableERC20)
     * @param from Sender address
     * @param amount Amount to transfer
     * @dev Overrides BaseEscrow._pullTokens. For EscrowableERC20, token must always be address(this).
     */
    function _pullTokens(address token, address from, uint256 amount) internal override {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        // Transfer from sender to contract using ERC20's internal _transfer
        _transfer(from, address(this), amount);
    }

    /**
     * @dev Record fee in totalFees (single token tracking)
     * @param token Token address (must be address(this) for EscrowableERC20)
     * @param amount Fee amount to record
     * @dev Overrides BaseEscrow._recordFee. Tracks fees in single totalFees variable.
     */
    function _recordFee(address token, uint256 amount) internal override {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        // MED-4: Prevent overflow when accumulating fees
        // currentFees is the current total accumulated fees before adding the new fee
        uint256 currentFees = totalFees;
        if (amount > type(uint256).max - currentFees) {
            revert FeeOverflow();
        }
        totalFees = currentFees + amount;
    }

    /**
     * @dev Transfer tokens using ERC20's internal _transfer
     * @param token Token address (must be address(this) for EscrowableERC20)
     * @param to Recipient address
     * @param amount Amount to transfer
     * @dev Overrides BaseEscrow._transferTokens. For EscrowableERC20, token must always be address(this).
     */
    function _transferTokens(address token, address to, uint256 amount) internal override {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        _transfer(address(this), to, amount);
    }

    /**
     * @dev Update escrow balance tracking
     * @param token Token address (must be address(this) for EscrowableERC20)
     * @param amount Amount to add or subtract
     * @param add True to add to totalHeldInEscrow, false to subtract
     * @dev Overrides BaseEscrow._updateEscrowBalance. Tracks total escrowed amount across all escrows.
     */
    function _updateEscrowBalance(address token, uint256 amount, bool add) internal override {
        // MED-3: Input validation
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);

        if (add) {
            totalHeldInEscrow += amount;
        } else {
            // CRIT-1: Prevent underflow that could break accounting
            if (totalHeldInEscrow < amount) {
                revert BalanceUnderflow(token, totalHeldInEscrow, amount);
            }
            totalHeldInEscrow -= amount;
        }
    }

    /**
     * @dev Emit EscrowTransferCreated event (without token parameter)
     * @param workflowId The escrow transfer ID
     * @param token Token address (must be address(this))
     * @param from Sender address
     * @param to Recipient address
     * @param amount Original escrow amount
     * @dev Overrides BaseEscrow._emitEscrowTransferCreated. Emits event without token parameter.
     */
    function _emitEscrowTransferCreated(
        uint256 workflowId,
        address token,
        address from,
        address to,
        uint256 amount
    ) internal override {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        emit EscrowTransferCreated(workflowId, from, to, amount);
    }

    /**
     * @dev Emit EscrowTransferCancelled event (without token parameter)
     * @param workflowId The escrow transfer ID
     * @param token Token address (must be address(this))
     * @param from Sender address
     * @param amount Original escrow amount
     * @dev Overrides BaseEscrow._emitEscrowTransferCancelled. Emits event without token parameter.
     */
    function _emitEscrowTransferCancelled(
        uint256 workflowId,
        address token,
        address from,
        uint256 amount
    ) internal override {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        emit EscrowTransferCancelled(workflowId, from, amount);
    }

    /**
     * @dev Emit EscrowTransferReleased event (without token parameter)
     * @param workflowId The escrow transfer ID
     * @param token Token address (must be address(this))
     * @param to Recipient address
     * @param amount Original escrow amount
     * @dev Overrides BaseEscrow._emitEscrowTransferReleased. Emits event without token parameter.
     */
    function _emitEscrowTransferReleased(
        uint256 workflowId,
        address token,
        address to,
        uint256 amount
    ) internal override {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        emit EscrowTransferReleased(workflowId, to, amount);
    }

    /**
     * @dev Delegate yield deposit to module
     * @param generationModule Yield generation module
     * @param workflowId The escrow transfer ID
     * @param token Token address (must be address(this))
     * @param amount Amount to deposit
     * @dev Overrides BaseEscrow._depositForYield. Delegates to generationModule's depositForYield().
     */
    function _depositForYield(
        IYieldGenerationModule generationModule,
        uint256 workflowId,
        address token,
        uint256 amount
    ) internal override {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        generationModule.depositForYield(workflowId, token, amount);
    }

    // ============ Module Getters ============

    /**
     * @dev Get the release strategy for an escrow
     * @param workflowId The escrow transfer ID
     * @return The release strategy module (from snapshot or default)
     */
    function _getReleaseStrategy(uint256 workflowId) internal view override returns (IReleaseStrategy) {
        address snapshot = moduleSnapshots[workflowId].releaseStrategy;
        return snapshot != address(0) ? IReleaseStrategy(snapshot) : defaultReleaseStrategy;
    }

    /**
     * @dev Get the resolution module for an escrow
     * @param workflowId The escrow transfer ID
     * @return The resolution module (from snapshot or default or BaseEscrow's disputeResolutionModule)
     */
    function _getResolutionModule(uint256 workflowId) internal view override returns (IResolutionModule) {
        address snapshot = moduleSnapshots[workflowId].resolutionModule;
        if (snapshot != address(0)) {
            return IResolutionModule(snapshot);
        }
        // Fall back to defaultDisputeResolutionModule if set, otherwise BaseEscrow's disputeResolutionModule
        if (address(defaultDisputeResolutionModule) != address(0)) {
            return defaultDisputeResolutionModule;
        }
        return super._getResolutionModule(workflowId);
    }

    /**
     * @dev Get the yield generation module for an escrow
     * @param workflowId The escrow transfer ID
     * @return The yield generation module (from snapshot or default)
     */
    function _getYieldGenerationModule(uint256 workflowId) internal view override returns (IYieldGenerationModule) {
        address snapshot = moduleSnapshots[workflowId].yieldGenerationModule;
        return snapshot != address(0) ? IYieldGenerationModule(snapshot) : defaultYieldGenerationModule;
    }

    /**
     * @dev Get the yield distribution module for an escrow
     * @param workflowId The escrow transfer ID
     * @return The yield distribution module (from snapshot or default)
     */
    function _getYieldDistributionModule(uint256 workflowId) internal view override returns (IYieldDistributionModule) {
        address snapshot = moduleSnapshots[workflowId].yieldDistributionModule;
        return snapshot != address(0) ? IYieldDistributionModule(snapshot) : defaultYieldDistributionModule;
    }

    // ============ Public Module Getters ============

    /**
     * @notice Get the release strategy for an escrow
     * @param workflowId The escrow transfer ID
     * @return The release strategy module
     */
    function getReleaseStrategy(uint256 workflowId) public view returns (IReleaseStrategy) {
        return _getReleaseStrategy(workflowId);
    }

    /**
     * @notice Get the resolution module for an escrow
     * @param workflowId The escrow transfer ID
     * @return The resolution module
     */
    function getResolutionModule(uint256 workflowId) public view returns (IResolutionModule) {
        return _getResolutionModule(workflowId);
    }

    /**
     * @notice Get the yield generation module for an escrow
     * @param workflowId The escrow transfer ID
     * @return The yield generation module
     */
    function getYieldGenerationModule(uint256 workflowId) public view returns (IYieldGenerationModule) {
        return _getYieldGenerationModule(workflowId);
    }

    /**
     * @notice Get the yield distribution module for an escrow
     * @param workflowId The escrow transfer ID
     * @return The yield distribution module
     */
    function getYieldDistributionModule(uint256 workflowId) public view returns (IYieldDistributionModule) {
        return _getYieldDistributionModule(workflowId);
    }

    // ============ Module Management (Slow Lane Queue/Activate) ============

    /**
     * @notice Disabled legacy entrypoint (use ModuleSnapshotRegistry)
     */
    function queueDefaultModule(ModuleType /* moduleType */, address /* newModule */) external view onlyRole(ROLE_TIMELOCK) {
        revert UseModuleSnapshotRegistry();
    }

    /**
     * @notice Disabled legacy entrypoint (use ModuleSnapshotRegistry)
     */
    function activateDefaultModule(ModuleType /* moduleType */) external view onlyRole(ROLE_TIMELOCK) {
        revert UseModuleSnapshotRegistry();
    }

    /**
     * @notice Disabled legacy entrypoint (use ModuleSnapshotRegistry)
     */
    function getPendingDefaultModule(ModuleType /* moduleType */) external pure returns (address, uint64, bool) {
        revert UseModuleSnapshotRegistry();
    }

    // ============ Fee Management ============

    /**
     * @notice Withdraw accumulated escrow fees
     * @return success True if withdrawal was successful
     * @dev Only the fee address can withdraw fees. Transfers all accumulated fees to the fee address.
     */
    function withdrawFees() public nonReentrant returns (bool) {
        if (_msgSender() != escrowFeeAddress) {
            revert NotFeeAddress(_msgSender(), escrowFeeAddress);
        }
        uint256 feeAmount = totalFees;
        if (feeAmount == 0) {
            revert NoFeesToWithdraw(address(this), feeAmount);
        }

        // Check balance before clearing state (checks-effects-interactions pattern)
        uint256 balance = balanceOf(address(this));
        if (balance < feeAmount) {
            revert InsufficientContractBalance(address(this), feeAmount, balance);
        }

        // Clear state AFTER successful transfer to prevent fee loss on failure
        // Note: If transfer fails, revert will restore state (Solidity 0.8+ automatic)
        _transfer(address(this), escrowFeeAddress, feeAmount);
        totalFees = 0;

        emit FeesWithdrawn(feeAmount);
        return true;
    }

    /**
     * @notice Recover ERC20 tokens sent to the contract
     * @dev Overrides BaseEscrow.recoverERC20 to validate against escrow accounting
     * @param token Token address to recover
     * @param recipient Address to receive the recovered tokens
     * @param amount Amount of tokens to recover
     * @return success Whether recovery succeeded
     * @dev Only ROLE_TIMELOCK can recover. Validates that recovery won't affect escrowed funds or fees.
     */
    function recoverERC20(
        address token,
        address recipient,
        uint256 amount
    ) external override onlyRole(ROLE_TIMELOCK) nonReentrant returns (bool) {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);

        uint256 balance = balanceOf(address(this));
        uint256 escrowBalance = totalHeldInEscrow;
        uint256 feeBalance = totalFees;

        // Calculate available excess (balance minus escrow and fees)
        uint256 available = balance > escrowBalance + feeBalance ? balance - escrowBalance - feeBalance : 0;

        // CRIT-2: Determine recovery amount - if amount == 0, recover all available excess
        uint256 recoveryAmount = amount == 0 ? available : amount;

        // CRIT-2: Critical validation - ensure requested amount doesn't exceed available excess
        if (recoveryAmount > available) {
            revert AmountExceedsAvailable(token, recoveryAmount, available);
        }
        if (recoveryAmount == 0) {
            revert NoTokensToRecover();
        }

        recoveryAmount = RecoveryLibrary.recoverERC20(token, recipient, recoveryAmount, balance);
        emit ERC20Recovered(token, recipient, recoveryAmount);
        return true;
    }
}

/**
 * @title EscrowableERC20Factory
 * @notice Factory contract for creating new EscrowableERC20 instances
 * @dev Allows deployment of new EscrowableERC20 tokens with custom parameters
 */
contract EscrowableERC20Factory {
    /**
     * @notice Create a new EscrowableERC20 token contract
     * @param name Token name
     * @param symbol Token symbol
     * @param escrowFee Escrow fee in basis points (e.g., 100 = 1%)
     * @param escrowFeeAddress Address to receive escrow fees
     * @param yieldOps Address of YieldOps contract
     * @param disputeOps Address of DisputeOps contract
     * @return Address of the newly deployed EscrowableERC20 contract
     */
    function createEscrowableERC20(
        string memory name,
        string memory symbol,
        uint256 escrowFee,
        address escrowFeeAddress,
        address yieldOps,
        address disputeOps
    ) public returns (address) {
        return address(new EscrowableERC20(name, symbol, escrowFee, escrowFeeAddress, yieldOps, disputeOps));
    }
}

contracts/core/EscrowVault.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import './BaseEscrow.sol';
import '../types/EscrowTypes.sol';
import '../interfaces/IReleaseStrategy.sol';
import '../shared/interfaces/IResolutionModule.sol';
import '../interfaces/IYieldGenerationModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
// PRIORITY: Removed unused IModuleRegistry import (only used in EscrowableERC20)
import './ModuleSnapshotRegistry.sol';

/**
 * @title EscrowVault
 * @notice Main escrow contract implementation supporting ERC20 tokens
 * @dev Concrete implementation of BaseEscrow that handles ERC20 token escrows.
 *      Supports multiple tokens, yield generation, dispute resolution, and module snapshots.
 *      Uses a pull model for token transfers and implements fee tracking per token.
 */
contract EscrowVault is BaseEscrow {
    using SafeERC20 for IERC20;

    /// @notice Default yield protocol fee (30%)
    uint256 public constant DEFAULT_YIELD_PROTOCOL_FEE_BPS = 3000; // 30% default

    mapping(address => uint256) public totalFeesPerToken;
    // Tracks total amount held in escrow per token (immutable amounts - no partial releases)
    mapping(address => uint256) public totalHeldInEscrowPerToken;

    // Module management contract (stores module state externally to reduce contract size)
    ModuleSnapshotRegistry public moduleManagement;

    // EscrowCreated and EscrowStateChanged already provide this information
    event FeesWithdrawn(address indexed token, uint256 amount);

    /// @notice Compact error for zero address validation (saves bytecode vs string-based errors)
    error ZeroAddress(uint8 which); // 1=fee, 2=yieldOps, 3=disputeOps, 4=moduleMgmt

    constructor(
        uint256 escrowFeeBps,
        address feeAddress,
        address yieldOpsAddress,
        address disputeOpsAddress,
        address moduleManagementAddress
    ) {
        // AccessControl initialization (required so tests/admin can grant roles)
        address deployer = _msgSender();
        _grantRole(DEFAULT_ADMIN_ROLE, deployer);
        _grantRole(ROLE_TIMELOCK, deployer);

        // Validate inputs (compact custom errors save bytecode)
        if (escrowFeeBps > MAX_ESCROW_FEE_BPS) revert InvalidEscrowFee(escrowFeeBps, MAX_ESCROW_FEE_BPS);
        if (feeAddress == address(0)) revert ZeroAddress(1);
        if (yieldOpsAddress == address(0)) revert ZeroAddress(2);
        if (disputeOpsAddress == address(0)) revert ZeroAddress(3);
        if (moduleManagementAddress == address(0)) revert ZeroAddress(4);

        // Set state variables
        escrowFee = escrowFeeBps;
        escrowFeeAddress = feeAddress;
        moduleManagement = ModuleSnapshotRegistry(moduleManagementAddress);
        yieldOps = YieldOps(yieldOpsAddress);
        disputeOps = DisputeOps(disputeOpsAddress);

        // Only set non-zero / non-default values (skip zero assignments to save bytecode)
        yieldProtocolFeeBps = DEFAULT_YIELD_PROTOCOL_FEE_BPS;

        // Set timeout config fields directly (avoid struct literal to save bytecode)
        timeoutConfig.maxDisputeDuration = 90 days;
        timeoutConfig.appealWindowDuration = 2 days;
        // Note: defaultAutoReleaseTime and defaultAutoCancelTime are zero by default, no need to set
    }


    /**
     * @notice Release escrow funds to recipient (sender-initiated)
     * @param workflowId The escrow ID
     * @return success Whether the release succeeded
     * @dev Only the sender (from address) can release. Transfers funds to recipient.
     */
    function releaseEscrowTransfer(uint256 workflowId) public nonReentrant whenNotPaused returns (bool) {
        _requirePending(workflowId);
        if (escrowTransfers[workflowId].from != _msgSender())
            revert NotSender(workflowId, _msgSender(), escrowTransfers[workflowId].from);
        _releaseEscrowTransfer(workflowId);
        return true;
    }

    function _pullTokens(address token, address from, uint256 amount) internal override {
        IERC20(token).safeTransferFrom(from, address(this), amount);
    }
    function _recordFee(address token, uint256 amount) internal override {
        // MED-4: Prevent overflow when accumulating fees
        // currentFees is the current total accumulated fees for this token before adding the new fee
        uint256 currentFees = totalFeesPerToken[token];
        if (amount > type(uint256).max - currentFees) {
            revert FeeOverflow();
        }
        totalFeesPerToken[token] = currentFees + amount;
    }
    function _depositForYield(
        IYieldGenerationModule generationModule,
        uint256 workflowId,
        address token,
        uint256 amount
    ) internal override {
        generationModule.depositForYield(workflowId, token, amount);
    }
    function _emitEscrowTransferCreated(
        uint256 workflowId,
        address token,
        address from,
        address to,
        uint256 amount
    ) internal override {
        // PRIORITY: Event removed - EscrowCreated already provides this information
    }
    function _transferTokens(address token, address to, uint256 amount) internal override {
        IERC20(token).safeTransfer(to, amount);
    }
    function _updateEscrowBalance(address token, uint256 amount, bool add) internal override {
        // MED-3: Input validation (use compact error)
        if (token == address(0)) revert ZeroAddress(0);

        if (add) {
            totalHeldInEscrowPerToken[token] += amount;
        } else {
            // CRIT-1: Prevent underflow that could break accounting
            if (totalHeldInEscrowPerToken[token] < amount) {
                revert BalanceUnderflow(token, totalHeldInEscrowPerToken[token], amount);
            }
            totalHeldInEscrowPerToken[token] -= amount;
        }
    }
    function _emitEscrowTransferCancelled(
        uint256 workflowId,
        address token,
        address from,
        uint256 amount
    ) internal override {
        // PRIORITY: Event removed - EscrowStateChanged already provides this information
    }
    function _emitEscrowTransferReleased(
        uint256 workflowId,
        address token,
        address to,
        uint256 amount
    ) internal override {
        // PRIORITY: Event removed - EscrowStateChanged already provides this information
    }

    // PRIORITY: Consolidated module getters to reduce bytecode
    function _getModuleAddress(uint256 workflowId, ModuleType moduleType) internal view returns (address) {
        address snapshotModule;
        if (moduleType == ModuleType.RELEASE) {
            snapshotModule = moduleSnapshots[workflowId].releaseStrategy;
        } else if (moduleType == ModuleType.RESOLUTION) {
            snapshotModule = moduleSnapshots[workflowId].resolutionModule;
        } else if (moduleType == ModuleType.YIELD_GEN) {
            snapshotModule = moduleSnapshots[workflowId].yieldGenerationModule;
        } else if (moduleType == ModuleType.YIELD_DIST) {
            snapshotModule = moduleSnapshots[workflowId].yieldDistributionModule;
        }

        if (snapshotModule != address(0)) {
            return snapshotModule;
        }

        // Query ModuleSnapshotRegistry for default module
        return moduleManagement.getDefaultModule(address(this), moduleType);
    }

    function _getReleaseStrategy(uint256 workflowId) internal view override returns (IReleaseStrategy) {
        return IReleaseStrategy(_getModuleAddress(workflowId, ModuleType.RELEASE));
    }

    function _getResolutionModule(uint256 workflowId) internal view override returns (IResolutionModule) {
        address moduleAddr = _getModuleAddress(workflowId, ModuleType.RESOLUTION);
        if (moduleAddr != address(0)) {
            return IResolutionModule(moduleAddr);
        }
        // Fallback to BaseEscrow's disputeResolutionModule
        return IResolutionModule(disputeResolutionModule);
    }

    function _getYieldGenerationModule(
        uint256 workflowId
    ) internal view override returns (IYieldGenerationModule) {
        return IYieldGenerationModule(_getModuleAddress(workflowId, ModuleType.YIELD_GEN));
    }

    function _getYieldDistributionModule(
        uint256 workflowId
    ) internal view override returns (IYieldDistributionModule) {
        return IYieldDistributionModule(_getModuleAddress(workflowId, ModuleType.YIELD_DIST));
    }

    // PRIORITY: Removed thin wrapper functions (queueDefaultModule, activateDefaultModule, getPendingDefaultModule)
    // Users should call ModuleSnapshotRegistry directly to reduce EscrowVault bytecode size

    bytes32 public constant ROLE_FEE_RECIPIENT = keccak256('ROLE_FEE_RECIPIENT');

    /**
     * @notice Withdraw accumulated fees for a specific token
     * @param token Token address to withdraw fees for
     * @return success Whether withdrawal succeeded
     * @dev Only fee recipient role can withdraw. Withdraws all accumulated fees for the token.
     */
    function withdrawFees(address token) external onlyRole(ROLE_FEE_RECIPIENT) nonReentrant returns (bool) {
        uint256 feeAmount = totalFeesPerToken[token];
        if (feeAmount == 0) revert NoFeesToWithdraw(token, feeAmount);

        // Check balance before clearing state (checks-effects-interactions pattern)
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (balance < feeAmount) {
            revert InsufficientContractBalance(token, feeAmount, balance);
        }

        // Clear state AFTER successful transfer to prevent fee loss on failure
        // Note: If transfer fails, revert will restore state (Solidity 0.8+ automatic)
        IERC20(token).safeTransfer(escrowFeeAddress, feeAmount);
        totalFeesPerToken[token] = 0;

        emit FeesWithdrawn(token, feeAmount);
        return true;
    }

    /**
     * @notice Recover ERC20 tokens (excluding escrow balances and fees)
     * @param token Token address to recover
     * @param recipient Recipient address
     * @param amount Amount to recover (0 = recover all excess)
     * @return success Whether recovery succeeded
     * @dev Only recovers tokens beyond escrow balances and fees. Requires ROLE_TIMELOCK.
     *      PRIORITY: Simplified to use safeTransfer directly, removed RecoveryLibrary dependency.
     */
    function recoverERC20(
        address token,
        address recipient,
        uint256 amount
    ) external override onlyRole(ROLE_TIMELOCK) nonReentrant returns (bool) {
        uint256 balance = IERC20(token).balanceOf(address(this));
        uint256 protected = totalHeldInEscrowPerToken[token] + totalFeesPerToken[token];
        uint256 available = balance > protected ? balance - protected : 0;
        uint256 recoveryAmount = amount == 0 ? available : amount;

        if (recoveryAmount == 0 || recoveryAmount > available) {
            revert AmountExceedsAvailable(token, recoveryAmount, available);
        }

        IERC20(token).safeTransfer(recipient, recoveryAmount);
        emit ERC20Recovered(token, recipient, recoveryAmount);
        return true;
    }
}

contracts/core/EscrowViewContract.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import './BaseEscrow.sol';
import '../types/EscrowTypes.sol';
import '../types/YieldPresets.sol';
import '../libraries/SettingsValidationLibrary.sol';
import '../libraries/DisputeManagementLibrary.sol';

/**
 * @title EscrowViewContract
 * @notice External view contract for frontend consumption
 * @dev PRIORITY 4: Extracted view getters from BaseEscrow to reduce contract size
 * 
 *      This contract reads BaseEscrow/EscrowVault via public storage/getters
 *      and repackages results for frontend consumption.
 *      
 *      Core contracts keep only essential on-chain getters:
 *      - escrowTransfers(uint256) (public array getter)
 *      - claimableBalances(workflowId, user) (if needed onchain)
 *      - getEscrowSummary(workflowId) - compact view with fixed-size fields
 */
contract EscrowViewContract {
    BaseEscrow public immutable escrowContract;

    /**
     * @notice Compact escrow summary (fixed-size fields only)
     */
    struct EscrowSummary {
        EscrowState state;
        address token;
        address from;
        address to;
        uint256 amountAfterFee;
        address resolver;
        uint256 autoReleaseTime;
        uint256 autoCancelTime;
    }

    constructor(address _escrowContract) {
        escrowContract = BaseEscrow(_escrowContract);
    }

    /**
     * @notice Get compact escrow summary
     * @param workflowId The escrow ID
     * @return summary Compact escrow summary
     */
    function getEscrowSummary(uint256 workflowId) external view returns (EscrowSummary memory summary) {
        // Public array getter returns tuple - unpack into struct
        (
            address token,
            address to,
            address from,
            address disputeResolver,
            uint256 amountAfterFee,
            uint64 autoReleaseTime,
            uint64 autoCancelTime,
            EscrowState escrowState,
            ,
        ) = escrowContract.escrowTransfers(workflowId);
        summary = EscrowSummary({
            state: escrowState,
            token: token,
            from: from,
            to: to,
            amountAfterFee: amountAfterFee,
            resolver: disputeResolver,
            autoReleaseTime: uint256(autoReleaseTime),
            autoCancelTime: uint256(autoCancelTime)
        });
    }

    /**
     * @notice Get escrow settings for an escrow
     * @param workflowId The escrow ID
     * @return settings Escrow settings
     */
    function getEscrowSettings(uint256 workflowId) external view returns (EscrowSettings memory settings) {
        // Public mapping getter returns tuple - unpack into struct
        // Note: yieldPreset is stored as YieldPreset enum in storage, but public getter returns as uint8
        (
            address customResolver,
            YieldPreset yieldPreset,
            uint256 autoReleaseTime,
            uint256 autoCancelTime
        ) = escrowContract.escrowSettings(workflowId);
        settings = EscrowSettings({
            customResolver: customResolver,
            yieldPreset: yieldPreset,
            autoReleaseTime: autoReleaseTime,
            autoCancelTime: autoCancelTime
        });
    }

    /**
     * @notice Get escrow status information
     * @param workflowId The escrow ID
     * @return status Current escrow state
     * @return isActive Whether escrow is active (PENDING or DISPUTED)
     * @return isPending Whether escrow is pending
     */
    function getEscrowStatusInfo(
        uint256 workflowId
    ) external view returns (EscrowState status, bool isActive, bool isPending) {
        // Public array getter returns tuple - extract only escrowState
        (
            , , , , , , ,
            EscrowState escrowState,
            ,
        ) = escrowContract.escrowTransfers(workflowId);
        status = escrowState;
        isActive = (status == EscrowState.PENDING || status == EscrowState.DISPUTED);
        isPending = (status == EscrowState.PENDING);
    }

    /**
     * @notice Get escrow participant addresses
     * @param workflowId The escrow ID
     * @return from Sender address
     * @return to Recipient address
     */
    function getEscrowParticipants(
        uint256 workflowId
    ) external view returns (address from, address to) {
        // Public array getter returns tuple - extract only from and to
        (
            , address toAddr, address fromAddr, , , , , , ,
        ) = escrowContract.escrowTransfers(workflowId);
        return (fromAddr, toAddr);
    }

    /**
     * @notice Get module snapshot for an escrow
     * @return snapshot Module snapshot containing all module addresses and fees at time of escrow creation
     * @dev Note: moduleSnapshots is internal in BaseEscrow, so this function cannot access it directly.
     *      Consider exposing moduleSnapshots as public mapping or adding a minimal getter in BaseEscrow.
     */
    function getModuleSnapshot(uint256) external pure returns (BaseEscrow.ModuleSnapshot memory) {
        // moduleSnapshots is internal in BaseEscrow, so we cannot access it directly
        // This requires BaseEscrow to expose moduleSnapshots as public or add a minimal getter
        revert('ModuleSnapshot accessor removed - use events emitted at escrow creation');
    }

    /**
     * @notice Get total amount deposited (after fee) for an escrow
     * @param workflowId The escrow ID
     * @return Total amount deposited after fee deduction
     */
    function getTotalDeposited(uint256 workflowId) external view returns (uint256) {
        // Public array getter returns tuple - extract only amountAfterFee
        (
            , , , , uint256 amountAfterFee, , , , ,
        ) = escrowContract.escrowTransfers(workflowId);
        return amountAfterFee;
    }

    /**
     * @notice Get total number of escrows created
     * @return Total count of escrows
     */
    function getEscrowCount() external pure returns (uint256) {
        // escrowTransfers is a public array in BaseEscrow
        // Access via public getter: escrowTransfers.length
        // Note: Solidity generates a public getter for public arrays, but .length is not directly accessible
        // We need to use a workaround or add a minimal getter in BaseEscrow
        revert('EscrowCount accessor removed - use events to track escrow count');
    }

    /**
     * @notice Get default escrow settings
     * @return Default escrow settings (all zeros/defaults)
     */
    function getDefaultSettings() external pure returns (EscrowSettings memory) {
        return SettingsValidationLibrary.getDefaultSettings();
    }

    /**
     * @notice Get pending settlement information
     * @param workflowId The escrow ID
     * @return exists Whether pending settlement exists
     * @return isRelease True if pending release, false if pending cancel
     * @return appealDeadline Appeal deadline timestamp
     * @return resolutionHash Resolution hash
     */
    function getPendingSettlement(
        uint256 workflowId
    ) external view returns (bool exists, bool isRelease, uint256 appealDeadline, bytes32 resolutionHash, bool canExecute) {
        // Public mapping getter returns tuple - unpack into struct
        (
            bool exists_,
            bool isRelease_,
            uint256 appealDeadline_,
            bytes32 resolutionHash_
        ) = escrowContract.pendingSettlements(workflowId);
        exists = exists_;
        isRelease = isRelease_;
        appealDeadline = appealDeadline_;
        resolutionHash = resolutionHash_;
        canExecute = exists && block.timestamp >= appealDeadline;
    }

    /**
     * @notice Get timeout configuration
     * @return config Timeout configuration
     */
    function getTimeoutConfig() external view returns (TimeoutConfig memory config) {
        // Public struct getter returns tuple - unpack into struct
        (
            uint256 defaultAutoReleaseTime,
            uint256 defaultAutoCancelTime,
            uint256 maxDisputeDuration,
            uint256 appealWindowDuration
        ) = escrowContract.timeoutConfig();
        config = TimeoutConfig({
            defaultAutoReleaseTime: defaultAutoReleaseTime,
            defaultAutoCancelTime: defaultAutoCancelTime,
            maxDisputeDuration: maxDisputeDuration,
            appealWindowDuration: appealWindowDuration
        });
    }

    /**
     * @notice Check if a dispute has timed out
     * @param workflowId The escrow ID
     * @return isTimedOut Whether dispute exceeded maxDisputeDuration
     * @return timeRemaining Seconds remaining until timeout (0 if timed out)
     */
    function isDisputeTimedOut(
        uint256 workflowId
    ) external view returns (bool isTimedOut, uint256 timeRemaining) {
        // Public array getter returns tuple - extract escrowState
        (
            , , , , , , ,
            EscrowState escrowState,
            ,
        ) = escrowContract.escrowTransfers(workflowId);

        // Public struct getter returns tuple - extract maxDisputeDuration
        (
            , , uint256 maxDisputeDuration,
        ) = escrowContract.timeoutConfig();

        (bool timedOut, uint256 remaining) = DisputeManagementLibrary.isTimedOut(
            workflowId,
            escrowState,
            escrowContract.disputeRaisedTimestamp(workflowId),
            maxDisputeDuration
        );
        return (timedOut, remaining);
    }
}

contracts/core/ModuleSnapshotRegistry.so.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import '../governance/SlowLaneQueueActivate.sol';
import '../interfaces/IReleaseStrategy.sol';
import '../interfaces/IYieldGenerationModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
import '../shared/interfaces/IResolutionModule.sol';
import './BaseEscrow.sol';

/**
 * @title ModuleSnapshotRegistry
 * @notice Centralized module management for escrow contracts
 * @dev Extracted from EscrowVault/EscrowableERC20 to reduce contract size.
 *      Handles queue/activate pattern for default modules with slow lane activation.
 */
contract ModuleSnapshotRegistry is AccessControl, SlowLaneQueueActivate {
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    /// @notice Module state for each escrow contract
    struct ModuleState {
        IReleaseStrategy defaultReleaseStrategy;
        IYieldGenerationModule defaultYieldGenerationModule;
        IYieldDistributionModule defaultYieldDistributionModule;
        IResolutionModule defaultResolutionModule;
        mapping(BaseEscrow.ModuleType => PendingAddress) pendingModules;
    }

    /// @notice Mapping from escrow contract to its module state
    mapping(address => ModuleState) public escrowModuleStates;

    /// @notice Events for module management
    event DefaultReleaseStrategyQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultReleaseStrategyActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );
    event DefaultYieldGenerationModuleQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultYieldGenerationModuleActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );
    event DefaultYieldDistributionModuleQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultYieldDistributionModuleActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );
    event DefaultResolutionModuleQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultResolutionModuleActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );

    /**
     * @notice Deploy the ModuleSnapshotRegistry.
     * @param initialAdmin Initial admin for bootstrap (expected to be replaced/managed by governance wiring).
     * @dev Grants `DEFAULT_ADMIN_ROLE` and `ROLE_TIMELOCK` to `initialAdmin` for initial setup.
     *      In production, `ROLE_TIMELOCK` should be held by the TimelockController.
     */
    constructor(address initialAdmin) {
        if (initialAdmin == address(0)) revert InvalidValue();
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialAdmin must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialAdmin);
    }

    /**
     * @notice Register an escrow contract for module management
     * @param escrowContract Address of the escrow contract
     * @dev Only ROLE_TIMELOCK can register escrow contracts (governance-controlled)
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidValue();
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    /**
     * @notice Queue a new default module
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to queue
     * @param module Address of the new module to queue
     * @dev Only the escrow contract itself can queue modules (via ROLE_ESCROW_CONTRACT)
     *      This ensures pending state is namespaced to the calling escrow contract.
     */
    function queueDefaultModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType,
        address module
    ) external onlyRole(ROLE_ESCROW_CONTRACT) {
        if (msg.sender != escrowContract) revert InvalidValue();
        if (module == address(0)) revert InvalidValue();

        ModuleState storage state = escrowModuleStates[escrowContract];
        _queueAddress(state.pendingModules[moduleType], module);

        // Emit appropriate event
        if (moduleType == BaseEscrow.ModuleType.RELEASE) {
            emit DefaultReleaseStrategyQueued(
                escrowContract,
                address(state.defaultReleaseStrategy),
                module,
                state.pendingModules[moduleType].eta
            );
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_GEN) {
            emit DefaultYieldGenerationModuleQueued(
                escrowContract,
                address(state.defaultYieldGenerationModule),
                module,
                state.pendingModules[moduleType].eta
            );
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_DIST) {
            emit DefaultYieldDistributionModuleQueued(
                escrowContract,
                address(state.defaultYieldDistributionModule),
                module,
                state.pendingModules[moduleType].eta
            );
        } else if (moduleType == BaseEscrow.ModuleType.RESOLUTION) {
            emit DefaultResolutionModuleQueued(
                escrowContract,
                address(state.defaultResolutionModule),
                module,
                state.pendingModules[moduleType].eta
            );
        }
    }

    /**
     * @notice Activate the queued default module
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to activate
     * @dev Only the escrow contract itself can activate modules (via ROLE_ESCROW_CONTRACT)
     *      Reverts if no module is queued for the given type, or if the ETA has not passed yet.
     */
    function activateDefaultModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType
    ) external onlyRole(ROLE_ESCROW_CONTRACT) {
        if (msg.sender != escrowContract) revert InvalidValue();

        ModuleState storage state = escrowModuleStates[escrowContract];
        address newModule = _activateAddress(state.pendingModules[moduleType]);
        address oldModule;

        if (moduleType == BaseEscrow.ModuleType.RELEASE) {
            oldModule = address(state.defaultReleaseStrategy);
            state.defaultReleaseStrategy = IReleaseStrategy(newModule);
            emit DefaultReleaseStrategyActivated(escrowContract, oldModule, newModule);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_GEN) {
            oldModule = address(state.defaultYieldGenerationModule);
            state.defaultYieldGenerationModule = IYieldGenerationModule(newModule);
            emit DefaultYieldGenerationModuleActivated(escrowContract, oldModule, newModule);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_DIST) {
            oldModule = address(state.defaultYieldDistributionModule);
            state.defaultYieldDistributionModule = IYieldDistributionModule(newModule);
            emit DefaultYieldDistributionModuleActivated(escrowContract, oldModule, newModule);
        } else if (moduleType == BaseEscrow.ModuleType.RESOLUTION) {
            oldModule = address(state.defaultResolutionModule);
            state.defaultResolutionModule = IResolutionModule(newModule);
            emit DefaultResolutionModuleActivated(escrowContract, oldModule, newModule);
        }
    }

    /**
     * @notice Get pending default module information
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to query
     * @return value Pending module address
     * @return eta Timestamp when activation becomes available
     * @return exists Whether a pending module exists
     */
    function getPendingDefaultModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType
    ) external view returns (address value, uint64 eta, bool exists) {
        ModuleState storage state = escrowModuleStates[escrowContract];
        return getPendingAddress(state.pendingModules[moduleType]);
    }

    /**
     * @notice Get default release strategy for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default release strategy
     */
    function getDefaultReleaseStrategy(
        address escrowContract
    ) external view returns (IReleaseStrategy) {
        return escrowModuleStates[escrowContract].defaultReleaseStrategy;
    }

    /**
     * @notice Get default yield generation module for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default yield generation module
     */
    function getDefaultYieldGenerationModule(
        address escrowContract
    ) external view returns (IYieldGenerationModule) {
        return escrowModuleStates[escrowContract].defaultYieldGenerationModule;
    }

    /**
     * @notice Get default yield distribution module for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default yield distribution module
     */
    function getDefaultYieldDistributionModule(
        address escrowContract
    ) external view returns (IYieldDistributionModule) {
        return escrowModuleStates[escrowContract].defaultYieldDistributionModule;
    }

    /**
     * @notice Get default resolution module for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default resolution module
     */
    function getDefaultResolutionModule(
        address escrowContract
    ) external view returns (IResolutionModule) {
        return escrowModuleStates[escrowContract].defaultResolutionModule;
    }

    /**
     * @notice Get default module address for an escrow contract by type
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to retrieve
     * @return The default module address (address(0) if not set)
     * @dev PRIORITY: Consolidated getter to reduce bytecode in escrow contracts
     */
    function getDefaultModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType
    ) external view returns (address) {
        ModuleState storage state = escrowModuleStates[escrowContract];
        if (moduleType == BaseEscrow.ModuleType.RELEASE) {
            return address(state.defaultReleaseStrategy);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_GEN) {
            return address(state.defaultYieldGenerationModule);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_DIST) {
            return address(state.defaultYieldDistributionModule);
        } else if (moduleType == BaseEscrow.ModuleType.RESOLUTION) {
            return address(state.defaultResolutionModule);
        }
        return address(0);
    }
}

contracts/CreateOps.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import './types/EscrowTypes.sol';
import './types/YieldPresets.sol';
import './libraries/SettingsValidationLibrary.sol';
import './libraries/YieldPresetLibrary.sol';
import './libraries/EscrowEncodingLibrary.sol';
import './shared/interfaces/IResolutionModule.sol';
import './interfaces/IYieldGenerationModule.sol';

/**
 * @title CreateOps
 * @notice External contract for escrow creation validation and computation
 * @dev Extracted from BaseEscrow to reduce contract size (Phase 3 size optimization)
 *
 *      Key design principles:
 *      - Compute → Apply: Returns creation result, BaseEscrow applies to state
 *      - No state writes: Does not modify BaseEscrow state
 *      - Validation only: Validates inputs and computes values
 *      - View-ish: Could be view functions but may query modules
 *      - Access Control: Restricted to authorized escrow contracts only
 *
 *      Pattern:
 *      BaseEscrow calls: computeEscrowCreation(...)
 *      CreateOps returns: (fee, amountAfterFee, resolver, yieldEnabled, shouldDepositYield)
 *      BaseEscrow applies: Stores struct, updates balances, emits events
 */
contract CreateOps is AccessControl {
    uint256 private constant ESCROW_FEE_DENOMINATOR = 10000;

    // ============ Role Constants ============
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_GUARDIAN = keccak256('ROLE_GUARDIAN');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    // ============ State Variables ============
    /// @notice Pause flag for yield deposits (emergency control)
    bool public yieldDepositsPaused;

    // ============ Custom Errors ============
    error ZeroOwner();
    error AlreadyPaused();
    error NotPaused();
    error NotAuthorized(address caller);

    // ============ Events ============
    /// @notice Emitted when yield deposits are paused
    event YieldDepositsPaused(address indexed caller, string reason);
    /// @notice Emitted when yield deposits are resumed
    event YieldDepositsResumed(address indexed caller);

    // Note: Monitoring events are emitted by BaseEscrow (EscrowCreated, EscrowStateChanged)
    // This contract is compute-only (view functions) and emits minimal events

    /**
     * @notice Constructor for CreateOps
     * @param initialOwner Address that will receive DEFAULT_ADMIN_ROLE (for initial setup only)
     */
    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert ZeroOwner();
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialOwner must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialOwner);
    }

    /**
     * @notice Register an escrow contract that can call computeEscrowCreation
     * @param escrow Address of the escrow contract (EscrowVault or EscrowableERC20)
     * @dev Only callable by ROLE_TIMELOCK (governance-controlled). Escrow contracts must be registered before use.
     */
    function registerEscrowContract(address escrow) external onlyRole(ROLE_TIMELOCK) {
        if (escrow == address(0)) revert InvalidAddress(ADDR_ESCROW_CONTRACT, escrow);
        _grantRole(ROLE_ESCROW_CONTRACT, escrow);
    }

    /**
     * @notice Pause yield deposits (emergency control)
     * @param reason Reason for pausing
     * @dev Can be called by ROLE_GUARDIAN (emergency) or ROLE_TIMELOCK (governance)
     *      When paused, all yield deposits are disabled regardless of user settings
     * @dev Reverts if already paused, or if caller is not authorized.
     */
    function pauseYieldDeposits(string memory reason) external {
        if (!hasRole(ROLE_TIMELOCK, msg.sender) && !hasRole(ROLE_GUARDIAN, msg.sender)) {
            revert NotAuthorized(msg.sender);
        }
        if (yieldDepositsPaused) revert AlreadyPaused();

        yieldDepositsPaused = true;
        emit YieldDepositsPaused(msg.sender, reason);
    }

    /**
     * @notice Resume yield deposits
     * @dev Only callable by ROLE_TIMELOCK. Guardian is down-only and cannot resume.
     * @dev Reverts if deposits are not paused.
     */
    function resumeYieldDeposits() external onlyRole(ROLE_TIMELOCK) {
        if (!yieldDepositsPaused) revert NotPaused();

        yieldDepositsPaused = false;
        emit YieldDepositsResumed(msg.sender);
    }

    /**
     * @dev Result of escrow creation computation
     */
    struct CreateResult {
        uint256 fee;                    // Escrow fee amount
        uint256 amountAfterFee;         // Amount after fee deduction
        address resolver;               // Default resolver address
        bool yieldEnabled;              // Whether yield is enabled for this escrow
        bool shouldDepositYield;        // Whether to attempt yield deposit
    }

    /**
     * @notice Compute escrow creation parameters
     * @param token Token address
     * @param to Recipient address
     * @param from Sender address
     * @param amount Total amount to escrow
     * @param settings Escrow configuration
     * @param escrowFee Escrow fee in basis points
     * @param workflowId The workflow ID (array index)
     * @param resolutionModule Resolution module address (for resolver determination)
     * @return result Creation computation result
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      BaseEscrow will apply the result after receiving it.
     *      Restricted to authorized escrow contracts only (EscrowVault, EscrowableERC20).
     */
    function computeEscrowCreation(
        address token,
        address to,
        address from,
        uint256 amount,
        EscrowSettings memory settings,
        uint256 escrowFee,
        uint256 workflowId,
        address resolutionModule
    ) external view onlyRole(ROLE_ESCROW_CONTRACT) returns (CreateResult memory result) {
        // Validate inputs
        if (token == address(0)) revert InvalidAddress(ADDR_TOKEN, token);
        if (amount == 0) revert AmountZero();
        SettingsValidationLibrary.validateEscrowAmount(amount);
        SettingsValidationLibrary.validateRecipient(to, from);

        // Use explicit validation time (always block.timestamp in production)
        uint256 validationTime = block.timestamp;
        SettingsValidationLibrary.validateEscrowSettings(settings, validationTime);

        // Fee calculation: fee = (amount * escrowFee) / ESCROW_FEE_DENOMINATOR
        result.fee = (amount * escrowFee) / ESCROW_FEE_DENOMINATOR;
        result.amountAfterFee = amount - result.fee;

        // Resolver determination: Query resolution module for default resolver
        result.resolver = _getDisputeResolverForNewEscrow(
            resolutionModule,
            workflowId,
            token,
            from,
            to,
            result.amountAfterFee
        );

        // Yield configuration
        result.yieldEnabled = YieldPresetLibrary.isYieldEnabled(settings.yieldPreset);
        if (result.yieldEnabled && !yieldDepositsPaused) {
            // Validate preset parameters (sender and recipient addresses)
            YieldPresetLibrary.validatePresetParams(settings.yieldPreset, from, to);
            // Validate yield opt-in amount (graceful degradation)
            result.shouldDepositYield = SettingsValidationLibrary.validateYieldOptIn(result.amountAfterFee, true);
        } else {
            result.shouldDepositYield = false;
        }

        return result;
    }

    /**
     * @notice Get dispute resolver for new escrow
     * @param resolutionModule Resolution module address to query
     * @param workflowId Escrow workflow ID being created
     * @param token Escrowed token address
     * @param from Escrow sender address
     * @param to Escrow recipient address
     * @param amount Amount after escrow fee deduction
     * @return resolver Dispute resolver address to snapshot into the new escrow (or address(0) on failure)
     * @dev Queries the resolution module for a resolver using a low-level staticcall.
     *      This function is best-effort: if the module is unset, not a contract, or reverts/returns malformed data,
     *      it returns `address(0)` and the caller can decide fallback behavior.
     */
    function _getDisputeResolverForNewEscrow(
        address resolutionModule,
        uint256 workflowId,
        address token,
        address from,
        address to,
        uint256 amount
    ) internal view returns (address resolver) {
        if (resolutionModule == address(0)) {
            return address(0);
        }

        // Check if resolutionModule is a contract (has code)
        if (resolutionModule.code.length == 0) {
            return address(0);
        }

        // Use low-level staticcall to query module
        bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(token, from, to, amount);
        (bool success, bytes memory data) = resolutionModule.staticcall(
            abi.encodeWithSelector(
                IResolutionModule.getDisputeResolver.selector,
                workflowId,
                escrowData
            )
        );

        if (!success || data.length < 64) {
            return address(0);
        }

        (resolver, ) = abi.decode(data, (address, uint8));
        return resolver;
    }
}

