// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

/**
 * @title DecentralizedResolverStructs
 * @notice Shared structs and enums for Decentralized Resolution Module
 */
interface DecentralizedResolverStructs {
    // ============ Enums ============

    enum ResolverRole {
        NONE, // 0 - Not a resolver
        RESOLVER, // 1 - Standard resolver (appointed by senior resolver)
        SENIOR_RESOLVER, // 2 - Senior resolver (appointed by DAO/owner)
        EXTERNAL // 3 - External resolver (e.g., Kleros)
    }

    enum ResolutionOutcome {
        NONE, // 0 - No resolution yet
        RELEASE, // 1 - Funds released to recipient
        CANCEL // 2 - Funds refunded to sender
    }

    enum DisputeStatus {
        Open, // 0 - Awaiting resolver decision
        Decided, // 1 - Decision submitted, appeal window open
        Escalated, // 2 - Escalated to next round
        Final // 3 - No further appeals possible
    }

    // ============ Structs ============

    struct ResolverMetadata {
        string name;
        string description;
        uint256 appointedAt;
        address appointedBy;
        bool active;
    }

    struct DisputeMetadata {
        // Round-based tracking (DR v1)
        uint8 currentRound; // 0=initial resolver, 1=senior resolver, 2=external (Kleros)
        DisputeStatus status; // Open, Decided, Escalated, Final
        // Per-round data (fixed 3 rounds: 0, 1, 2)
        address[3] resolverAtRound; // Resolver assigned for each round
        ResolutionOutcome[3] decisionAtRound; // Decision submitted for each round
        uint256[3] decidedAtRound; // Timestamp when decision was submitted
        uint256[3] appealDeadline; // Deadline to appeal each round's decision
        // DR v2: Appeal bond tracking per round
        address[3] bondDepositorAtRound; // Who deposited appeal bond for this round
        uint256[3] bondAmountAtRound; // Appeal bond amount for this round
        address[3] bondTokenAtRound; // Token used for appeal bond
        bool[3] bondRefundedAtRound; // Whether bond was refunded (vs paid to resolvers)
        // Current state
        address escalatedBy; // Who initiated current escalation
        uint256 escalationTimestamp; // When current escalation happened
        uint256 assignedAt; // When current resolver was assigned
        uint256 resolveBy; // Deadline for current resolver to submit decision
        bytes resolutionData; // Additional resolution data
    }

    struct EscalationConfig {
        address resolver; // Resolver for this level (or address(0) for dynamic)
        uint256 fee; // Fee required to escalate to this level
        bool enabled; // Whether this level is enabled
    }

    struct PendingEscalationConfig {
        uint8 level;
        EscalationConfig config;
        uint64 eta;
        bool exists;
    }

    struct ResolutionTableEntry {
        uint8 maxRound; // Maximum round (0-2: 0=resolver only, 1=+senior, 2=+Kleros)
        uint256 escalationFee; // Fee required for escalation (legacy, use cost curves in v2)
        bool enabled; // Whether this entry is active
        string categoryName; // Human-readable category name
    }

    struct ResolverCapacity {
        uint256 maxConcurrentDisputes; // Maximum disputes resolver can handle
        uint256 currentDisputes; // Current number of active disputes
        bool acceptsNewDisputes; // Whether resolver accepts new disputes
    }

    struct ResolverStats {
        // EMA-based performance score (DR v1)
        uint256 emaScore; // EMA performance score (0-1e6 fixed point, 1e6 = perfect)
        uint256 lastScoreUpdate; // Timestamp of last EMA update
        // Objective counters
        uint256 casesAssigned; // Total cases assigned
        uint256 casesDecided; // Cases decided on time
        uint256 timeoutsAccept; // Failed to accept assignment (DR v1)
        uint256 timeoutsResolve; // Failed to resolve on time (DR v1)
        uint256 reversals; // Decisions reversed on escalation
        // Timing metrics
        uint256 totalResolutionTime; // Cumulative resolution time (for average)
        uint256 lastActive; // Last activity timestamp
        // Legacy fields (kept for backward compatibility during migration)
        uint256 disputesResolved; // Deprecated: use casesDecided
        uint256 disputesEscalated; // Deprecated: tracked separately
        uint256 qualityScore; // Deprecated: use emaScore
        // Manual controls
        uint256 assignmentWeight; // Manual override (0-10000 bps, 0=excluded)
    }

    // ============ DR v2 Structures ============

    enum CostCurveType {
        LINEAR, // cost(k) = baseCost + stepSize * k
        QUADRATIC, // cost(k) = baseCost + stepSize * k^2 (recommended default)
        GEOMETRIC // cost(k) = baseCost * multiplier^k
    }

    struct EscalationCostConfig {
        CostCurveType curveType; // Type of cost curve (DR v2)
        uint256 baseCost; // Base cost for escalation (in wei or token units)
        uint256 stepSize; // Step size for cost curve calculation
        uint256 multiplier; // Multiplier for geometric curves (r > 1, scaled by 1e18)
        address bondToken; // Token address for bond (address(0) = ETH)
        bool enabled; // Whether this cost config is enabled
    }

    struct AppealBond {
        address depositor; // Address that deposited the bond
        uint256 amount; // Bond amount
        address token; // Token address
        uint256 depositedAt; // Timestamp when bond was deposited
        bool refunded; // Whether bond has been refunded
    }
}

contracts/DisputeOps.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import './shared/interfaces/IResolutionModule.sol';
import './types/EscrowTypes.sol';

/**
 * @title DisputeOps
 * @notice External contract for dispute escalation orchestration
 * @dev Extracted from BaseEscrow to reduce contract size (Phase 2 size optimization)
 *
 *      Key design principles (from updated plan):
 *      - Compute → Apply: Returns escalation result, BaseEscrow applies to state
 *      - No callbacks: Does not write to BaseEscrow state
 *      - Atomic: Single call computes all escalation logic
 *      - View-ish: Could be view function but module may update counters
 *
 *      Pattern:
 *      BaseEscrow calls: computeEscalation(workflowId, caller, escrowData)
 *      DisputeOps returns: (newResolver, newLevel, escalationFee)
 *      BaseEscrow applies: Updates state and collects fees
 */
contract DisputeOps is AccessControl {
    // ============ Role Constants ============
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    // ============ Custom Errors ============
    error ZeroOwner();
    /**
     * @notice Constructor for DisputeOps
     * @param initialOwner Address that will receive DEFAULT_ADMIN_ROLE (for initial setup only)
     */
    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert ZeroOwner();
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialOwner must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialOwner);
    }

    /**
     * @notice Register an escrow contract (grants it ROLE_ESCROW_CONTRACT)
     * @param escrowContract Address of the escrow contract
     * @dev Only ROLE_TIMELOCK can register escrow contracts (governance-controlled)
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidAddress(ADDR_ESCROW_CONTRACT, escrowContract);
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    /**
     * @dev Result of escalation computation
     */
    struct EscalationResult {
        bool success; // Whether escalation is allowed
        address newResolver; // New dispute resolver address
        uint8 newLevel; // New escalation level
        uint8 currentLevel; // Current escalation level (for event)
        uint256 escalationFee; // Fee required for escalation
        string failureReason; // Reason if escalation not allowed
    }

    /**
     * @notice Compute escalation for a disputed escrow
     * @param resolutionModule Address of the resolution module
     * @param workflowId Escrow workflow ID
     * @param caller Address initiating the escalation (msg.sender from BaseEscrow)
     * @param from Escrow sender address
     * @param to Escrow recipient address
     * @param token Token address
     * @param amountAfterFee Amount after fee deduction (what's actually held in escrow)
     * @param escrowState Current escrow state
     * @return result Escalation computation result
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      It may call the resolution module which might update its own counters.
     *      BaseEscrow will apply the result after receiving it.
     *      Only authorized escrow contracts can call this function
     */
    function computeEscalation(
        address resolutionModule,
        uint256 workflowId,
        address caller,
        address from,
        address to,
        address token,
        uint256 amountAfterFee,
        EscrowState escrowState
    ) external onlyRole(ROLE_ESCROW_CONTRACT) returns (EscalationResult memory result) {
        result.success = false;

        // Validate caller is participant (BaseEscrow should have checked this, but double-check)
        if (caller != from && caller != to) {
            result.failureReason = 'Caller not participant';
            return result;
        }

        // Validate state is DISPUTED
        if (escrowState != EscrowState.DISPUTED) {
            result.failureReason = 'Not in disputed state';
            return result;
        }

        // Validate module exists
        if (resolutionModule == address(0)) {
            result.failureReason = 'Resolution module not configured';
            return result;
        }

        // Encode escrow data for module
        bytes memory escrowData = abi.encode(token, from, to, amountAfterFee);

        // Get current level from module
        try IResolutionModule(resolutionModule).getDisputeResolver(workflowId, escrowData) returns (
            address /* currentResolver */,
            uint8 currentLevel
        ) {
            result.currentLevel = currentLevel;
        } catch {
            result.failureReason = 'Failed to get current level';
            return result;
        }

        // Validate only the disagreed-with participant can appeal
        // Try to get decision at current round from module (if supported)
        // For DecentralizedResolutionModule, we can call getDecisionAtRound
        // Use low-level call since this function is not in IResolutionModule interface
        (bool decisionSuccess, bytes memory decisionData) = resolutionModule.staticcall(
            abi.encodeWithSignature('getDecisionAtRound(uint256,uint8)', workflowId, result.currentLevel)
        );

        if (decisionSuccess && decisionData.length >= 32) {
            // Decode the uint8 return value
            uint8 decision;
            assembly {
                decision := mload(add(decisionData, 0x20))
                // Mask to get only the first byte (uint8)
                decision := and(decision, 0xff)
            }

            // decision: 0 = NONE, 1 = RELEASE, 2 = CANCEL (matching ResolutionOutcome enum)
            if (decision == 1) {
                // RELEASE means recipient wins, so only sender (from) can appeal
                if (caller != from) {
                    result.failureReason = 'Only sender can appeal RELEASE decision';
                    return result;
                }
            } else if (decision == 2) {
                // CANCEL means sender wins, so only recipient (to) can appeal
                if (caller != to) {
                    result.failureReason = 'Only recipient can appeal CANCEL decision';
                    return result;
                }
            } else if (decision == 0) {
                // NONE - no decision yet, can't appeal
                result.failureReason = 'No decision to appeal';
                return result;
            }
            // If decision is valid and caller matches, continue
        }
        // If we can't get decision (e.g., module doesn't support it), allow escalation
        // This maintains backward compatibility with modules that don't track decisions

        // Check if escalation is allowed and get fee
        try
            IResolutionModule(resolutionModule).canEscalate(
                workflowId,
                result.currentLevel,
                escrowData
            )
        returns (bool canEscalate, address /* nextResolver */, uint256 fee) {
            if (!canEscalate) {
                result.failureReason = 'Escalation not allowed';
                return result;
            }
            result.escalationFee = fee;
        } catch {
            result.failureReason = 'Failed to check escalation eligibility';
            return result;
        }

        // Execute escalation in module (module may update its state)
        try IResolutionModule(resolutionModule).executeEscalation(workflowId, escrowData) returns (
            bool escalationSuccess,
            address newResolver,
            uint8 newLevel
        ) {
            if (!escalationSuccess) {
                result.failureReason = 'Module rejected escalation';
                return result;
            }

            // Validate returned values
            if (newResolver == address(0)) {
                result.failureReason = 'Module returned zero address';
                return result;
            }

            result.success = true;
            result.newResolver = newResolver;
            result.newLevel = newLevel;
            return result;
        } catch {
            result.failureReason = 'Module escalation call failed';
            return result;
        }
    }

    /**
     * @notice Validate escalation fee payment
     * @param requiredFee Fee required by escalation
     * @param paidFee Fee actually paid (msg.value)
     * @return valid Whether payment is sufficient
     * @return excessRefund Amount to refund to caller
     * @dev Helper function for BaseEscrow to validate fee payment
     */
    function validateEscalationFee(
        uint256 requiredFee,
        uint256 paidFee
    ) external pure returns (bool valid, uint256 excessRefund) {
        if (requiredFee > 0 && paidFee < requiredFee) {
            return (false, 0);
        }

        valid = true;
        if (paidFee > requiredFee) {
            excessRefund = paidFee - requiredFee;
        }
        return (valid, excessRefund);
    }

    /**
     * @notice Encode escrow data for resolution module
     * @param token Token address
     * @param from Sender address
     * @param to Recipient address
     * @param amountAfterFee Amount after fee deduction (what's actually held in escrow)
     * @return Encoded escrow data
     * @dev Public helper for encoding - can be used by BaseEscrow or externally
     */
    function encodeEscrowData(
        address token,
        address from,
        address to,
        uint256 amountAfterFee
    ) external pure returns (bytes memory) {
        return abi.encode(token, from, to, amountAfterFee);
    }

}

contracts/governance/SlowLaneQueueActiva.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

/**
 * @title SlowLaneQueueActivate
 * @notice Abstract contract providing two-step queue/activate pattern for Slow lane governance
 * @dev Enforces 7-day delay for high-risk changes (module swaps, fee recipient, etc.)
 *
 * Usage:
 * 1. Inherit this contract
 * 2. Add storage for pending values (PendingAddress or PendingUint)
 * 3. Implement queueX() function calling _queueAddress() or _queueUint()
 * 4. Implement activateX() function calling _activateAddress() or _activateUint()
 *
 * Pattern:
 * - queueX() stores pending value and ETA (now + 7 days)
 * - activateX() checks ETA has passed, then applies the change
 * - This enforces 7-day delay on top of Timelock's 48h delay
 *
 * Example:
 * ```solidity
 * PendingAddress private _pendingFeeRecipient;
 *
 * function queueFeeRecipient(address newAddr) external onlyRole(ROLE_TIMELOCK) {
 *     _queueAddress(_pendingFeeRecipient, newAddr);
 *     emit FeeRecipientQueued(feeRecipient, newAddr, _pendingFeeRecipient.eta);
 * }
 *
 * function activateFeeRecipient() external onlyRole(ROLE_TIMELOCK) {
 *     address old = feeRecipient;
 *     feeRecipient = _activateAddress(_pendingFeeRecipient);
 *     emit FeeRecipientActivated(old, feeRecipient);
 * }
 * ```
 */
abstract contract SlowLaneQueueActivate {
    /// @notice Slow lane delay: 7 days
    uint256 public constant SLOW_DELAY = 7 days;

    /// @notice Pending address change with ETA
    struct PendingAddress {
        address value;
        uint64 eta; // Unix timestamp when activation is allowed
        bool exists;
    }

    /// @notice Pending uint256 change with ETA
    struct PendingUint {
        uint256 value;
        uint64 eta; // Unix timestamp when activation is allowed
        bool exists;
    }

    /// @notice Error thrown when trying to activate before ETA
    error NotReady(uint64 eta);

    /// @notice Error thrown when no pending change exists
    error NoPending();

    /// @notice Error thrown when value is invalid (e.g., zero address)
    error InvalidValue();

    /**
     * @notice Queue an address change
     * @param pending Storage reference to PendingAddress
     * @param newValue New address value to queue
     * @dev Sets pending value and ETA = now + SLOW_DELAY
     */
    function _queueAddress(PendingAddress storage pending, address newValue) internal {
        if (newValue == address(0)) {
            revert InvalidValue();
        }
        pending.value = newValue;
        pending.eta = uint64(block.timestamp + SLOW_DELAY); // forge-lint: disable-line(unsafe-typecast)
        pending.exists = true;
    }

    /**
     * @notice Activate a queued address change
     * @param pending Storage reference to PendingAddress
     * @return activatedValue The activated address value
     * @dev Reverts if no pending change or ETA not reached
     */
    function _activateAddress(PendingAddress storage pending) internal returns (address) {
        if (!pending.exists) {
            revert NoPending();
        }
        if (block.timestamp < pending.eta) {
            revert NotReady(pending.eta);
        }
        address value = pending.value;
        // Clear all fields
        pending.value = address(0);
        pending.eta = 0;
        pending.exists = false;
        return value;
    }

    /**
     * @notice Queue a uint256 change
     * @param pending Storage reference to PendingUint
     * @param newValue New uint256 value to queue
     * @dev Sets pending value and ETA = now + SLOW_DELAY
     */
    function _queueUint(PendingUint storage pending, uint256 newValue) internal {
        pending.value = newValue;
        pending.eta = uint64(block.timestamp + SLOW_DELAY); // forge-lint: disable-line(unsafe-typecast)
        pending.exists = true;
    }

    /**
     * @notice Activate a queued uint256 change
     * @param pending Storage reference to PendingUint
     * @return activatedValue The activated uint256 value
     * @dev Reverts if no pending change or ETA not reached
     */
    function _activateUint(PendingUint storage pending) internal returns (uint256) {
        if (!pending.exists) {
            revert NoPending();
        }
        if (block.timestamp < pending.eta) {
            revert NotReady(pending.eta);
        }
        uint256 value = pending.value;
        // Clear all fields
        pending.value = 0;
        pending.eta = 0;
        pending.exists = false;
        return value;
    }

    /**
     * @notice Get pending address value (if exists)
     * @param pending Storage reference to PendingAddress
     * @return value Pending address value
     * @return eta Timestamp when activation is allowed
     * @return exists Whether a pending change exists
     */
    function getPendingAddress(
        PendingAddress storage pending
    ) internal view returns (address value, uint64 eta, bool exists) {
        return (pending.value, pending.eta, pending.exists);
    }

    /**
     * @notice Get pending uint256 value (if exists)
     * @param pending Storage reference to PendingUint
     * @return value Pending uint256 value
     * @return eta Timestamp when activation is allowed
     * @return exists Whether a pending change exists
     */
    function getPendingUint(
        PendingUint storage pending
    ) internal view returns (uint256 value, uint64 eta, bool exists) {
        return (pending.value, pending.eta, pending.exists);
    }
}

