// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '../types/EscrowTypes.sol';

/**
 * @title SettingsValidationLibrary
 * @notice Library for validating escrow settings with bounds enforcement
 * @dev Extracted from BaseEscrow to reduce contract size. Phase 6: Added bounds validation.
 */
library SettingsValidationLibrary {
    /// @notice Maximum auto time duration (10 years in seconds)
    uint256 public constant MAX_AUTO_TIME_DURATION = 10 * 365 * 24 * 60 * 60;

    // Phase 6: Bounds constants
    uint256 public constant MAX_AUTO_TIME_DAYS = 30 days;
    uint256 public constant MAX_ATTACHMENTS = 20;
    uint256 public constant MAX_FEE_BPS = 200; // 2%
    uint256 public constant MIN_RESOLUTION_DELAY = 48 hours;
    uint256 public constant MAX_RESOLUTION_DELAY = 30 days;
    uint256 public constant MIN_YIELD_RECIPIENTS = 1;
    uint256 public constant MAX_YIELD_RECIPIENTS = 10;
    uint256 public constant BPS_DENOMINATOR = 10_000;

    // New constraints
    uint256 public constant MIN_ESCROW_AMOUNT = 1000; // Minimum escrow amount (1000 wei)
    uint256 public constant MAX_ESCROW_DURATION = 365 days; // Maximum escrow duration (1 year)
    uint256 public constant MIN_YIELD_DEPOSIT = 1000e6; // Minimum yield deposit (1000 tokens with 6 decimals)

    // Phase 6: Custom errors (using different names to avoid conflicts with EscrowTypes)
    error OutOfBounds(bytes32 key, uint256 value, uint256 min, uint256 max);
    error InvalidAddressKey(bytes32 key);
    error InvalidArrayLength(bytes32 key, uint256 a, uint256 b);
    error InvalidBpsSum(uint256 sum);
    error TooManyRecipients(uint256 n, uint256 max);
    error DuplicateRecipient(address recipient);

    /**
     * @dev Validate a single auto time value
     * @param autoTime The auto time to validate (0 means no auto time, which is valid)
     * @param currentTime Current block timestamp
     * @dev Reverts if autoTime is in the past or exceeds MAX_AUTO_TIME_DURATION from current block timestamp
     */
    function validateAutoTime(
        uint256 autoTime,
        uint256 currentTime
    ) internal pure {
        if (autoTime == 0) {
            return; // 0 means no auto time, which is valid
        }

        // Validate time is in the future
        if (autoTime <= currentTime) {
            revert InvalidAutoTime(AUTO_TIME_IN_PAST, autoTime, currentTime);
        }

        // Validate time doesn't exceed maximum duration
        uint256 maxAllowedTime = currentTime + MAX_AUTO_TIME_DURATION;
        if (autoTime > maxAllowedTime) {
            revert AutoTimeExceedsMaxLimit(autoTime, maxAllowedTime);
        }
    }

    /**
     * @dev Validate escrow settings
     * @param settings EscrowSettings struct to validate
     * @param currentTime Current block timestamp
     * @dev Reverts if settings are invalid (e.g., both auto times set, invalid times, etc.)
     */
    function validateEscrowSettings(
        EscrowSettings memory settings,
        uint256 currentTime
    ) internal view {
        // Validate auto times
        if (settings.autoReleaseTime != 0 && settings.autoCancelTime != 0) {
            revert CannotSetBothAutoTimes(settings.autoReleaseTime, settings.autoCancelTime);
        }

        // Validate auto times using helper function
        validateAutoTime(settings.autoReleaseTime, currentTime);
        validateAutoTime(settings.autoCancelTime, currentTime);

        // Validate maximum escrow duration (for auto times)
        if (settings.autoReleaseTime > 0) {
            uint256 maxAllowedTime = currentTime + MAX_ESCROW_DURATION;
            if (settings.autoReleaseTime > maxAllowedTime) {
                revert OutOfBounds(
                    'autoReleaseTime',
                    settings.autoReleaseTime,
                    currentTime + 1,
                    maxAllowedTime
                );
            }
        }
        if (settings.autoCancelTime > 0) {
            uint256 maxAllowedTime = currentTime + MAX_ESCROW_DURATION;
            if (settings.autoCancelTime > maxAllowedTime) {
                revert OutOfBounds(
                    'autoCancelTime',
                    settings.autoCancelTime,
                    currentTime + 1,
                    maxAllowedTime
                );
            }
        }

        // Validate custom dispute resolver if set
        if (settings.customResolver != address(0)) {
            // Validate resolver is a contract
            if (settings.customResolver.code.length == 0) {
                revert InvalidAddressKey('customResolver');
            }
        }

        // DEPRECATED: Per-escrow yield distribution has been removed in favor of yield presets.
        // Distribution is derived at runtime from `settings.yieldPreset` and participant addresses.
    }

    /**
     * @notice Validate escrow amount
     * @param amount The escrow amount to validate
     * @dev Reverts if amount is below minimum
     */
    function validateEscrowAmount(uint256 amount) internal pure {
        if (amount < MIN_ESCROW_AMOUNT) {
            revert OutOfBounds(
                'amount',
                amount,
                MIN_ESCROW_AMOUNT,
                type(uint256).max
            );
        }
    }

    /**
     * @notice Validate recipient address
     * @param recipient The recipient address
     * @param sender The sender address
     * @dev Reverts if recipient is zero address or same as sender
     */
    function validateRecipient(address recipient, address sender) internal pure {
        if (recipient == address(0)) {
            revert InvalidAddressKey('recipient');
        }
        if (recipient == sender) {
            revert InvalidAddressKey('sender');
        }
    }

    /**
     * @notice Validate yield opt-in amount
     * @param amount The amount to validate (amount after fee)
     * @param yieldEnabled Whether yield is enabled
     * @return shouldEnableYield Whether yield should actually be enabled (may be disabled if amount too small)
     * @dev Returns false if yield is enabled but amount is below minimum (graceful degradation)
     */
    function validateYieldOptIn(uint256 amount, bool yieldEnabled) internal pure returns (bool shouldEnableYield) {
        if (!yieldEnabled) {
            return false;
        }
        // Graceful degradation: disable yield if amount is too small
        if (amount < MIN_YIELD_DEPOSIT) {
            return false; // Don't revert, just disable yield
        }
        return true;
    }

    /**
     * @dev Get default escrow settings
     * @return Default settings struct with all fields set to default values
     */
    function getDefaultSettings() internal pure returns (EscrowSettings memory) {
        return
            EscrowSettings({
                customResolver: address(0),
                yieldPreset: YieldPreset.OFF, // Default: yield off
                autoReleaseTime: 0,
                autoCancelTime: 0
            });
    }

    // ============ Phase 6: Bounds Validation Functions ============

    /**
     * @notice Validate auto cancel time (default setting)
     * @param t Absolute timestamp (0 means disabled, which is valid)
     * @dev Bounds: t must be within 30 days from current block timestamp
     */
    function validateAutoCancel(uint256 t) internal view {
        if (t == 0) {
            return; // 0 means disabled, which is valid
        }
        uint256 currentTime = block.timestamp;
        if (t <= currentTime) {
            revert OutOfBounds(
                'autoCancelTime',
                t,
                currentTime + 1,
                currentTime + MAX_AUTO_TIME_DAYS
            );
        }
        if (t > currentTime + MAX_AUTO_TIME_DAYS) {
            revert OutOfBounds(
                'autoCancelTime',
                t,
                currentTime + 1,
                currentTime + MAX_AUTO_TIME_DAYS
            );
        }
    }

    /**
     * @notice Validate auto release time (default setting)
     * @param t Absolute timestamp (0 means disabled, which is valid)
     * @dev Bounds: t must be within 30 days from current block timestamp
     */
    function validateAutoRelease(uint256 t) internal view {
        if (t == 0) {
            return; // 0 means disabled, which is valid
        }
        uint256 currentTime = block.timestamp;
        if (t <= currentTime) {
            revert OutOfBounds(
                'autoReleaseTime',
                t,
                currentTime + 1,
                currentTime + MAX_AUTO_TIME_DAYS
            );
        }
        if (t > currentTime + MAX_AUTO_TIME_DAYS) {
            revert OutOfBounds(
                'autoReleaseTime',
                t,
                currentTime + 1,
                currentTime + MAX_AUTO_TIME_DAYS
            );
        }
    }

    /**
     * @notice Validate max attachments
     * @param n Maximum number of attachments
     * @dev Bounds: 0 <= n <= 20
     */
    function validateMaxAttachments(uint256 n) internal pure {
        if (n > MAX_ATTACHMENTS) {
            revert OutOfBounds('maxAttachments', n, 0, MAX_ATTACHMENTS);
        }
    }

    /**
     * @notice Validate fee in basis points
     * @param bps Fee in basis points (100 = 1%)
     * @dev Bounds: 0 <= bps <= 200 (0% to 2%)
     */
    function validateFeeBps(uint256 bps) internal pure {
        if (bps > MAX_FEE_BPS) {
            revert OutOfBounds('escrowFee', bps, 0, MAX_FEE_BPS);
        }
    }

    /**
     * @notice Validate resolution module delay
     * @param d Delay in seconds
     * @dev Bounds: 48h <= d <= 30 days
     */
    function validateResolutionDelay(uint256 d) internal pure {
        if (d < MIN_RESOLUTION_DELAY) {
            revert OutOfBounds('resolutionDelay', d, MIN_RESOLUTION_DELAY, MAX_RESOLUTION_DELAY);
        }
        if (d > MAX_RESOLUTION_DELAY) {
            revert OutOfBounds('resolutionDelay', d, MIN_RESOLUTION_DELAY, MAX_RESOLUTION_DELAY);
        }
    }

    /**
     * @notice Validate yield distribution configuration
     * @param recipients Array of recipient addresses
     * @param bps Array of basis points for each recipient
     * @dev Validates:
     *      - 1 <= recipients.length <= 10
     *      - recipients.length == bps.length
     *      - Sum of bps == 10_000
     *      - All recipients non-zero
     *      - No duplicate recipients
     */
    function validateYieldDistribution(
        address[] memory recipients,
        uint256[] memory bps
    ) internal pure {
        uint256 length = recipients.length;

        // Check recipient count bounds
        if (length < MIN_YIELD_RECIPIENTS) {
            revert OutOfBounds(
                'yieldRecipients',
                length,
                MIN_YIELD_RECIPIENTS,
                MAX_YIELD_RECIPIENTS
            );
        }
        if (length > MAX_YIELD_RECIPIENTS) {
            revert TooManyRecipients(length, MAX_YIELD_RECIPIENTS);
        }

        // Check array lengths match
        if (length != bps.length) {
            revert InvalidArrayLength('yieldDistribution', length, bps.length);
        }

        // Validate recipients and calculate sum
        uint256 sum = 0;
        for (uint256 i = 0; i < length; i++) {
            // Check recipient is non-zero
            if (recipients[i] == address(0)) {
                revert InvalidAddressKey('yieldRecipient');
            }

            // Check for duplicates
            for (uint256 j = i + 1; j < length; j++) {
                if (recipients[i] == recipients[j]) {
                    revert DuplicateRecipient(recipients[i]);
                }
            }

            sum += bps[i];
        }

        // Check sum equals 100%
        if (sum != BPS_DENOMINATOR) {
            revert InvalidBpsSum(sum);
        }
    }

    /**
     * @notice Validate address is non-zero
     * @param a Address to validate
     * @param key Key for error message
     */
    function validateNonZero(address a, bytes32 key) internal pure {
        if (a == address(0)) {
            revert InvalidAddressKey(key);
        }
    }
}

contracts/libraries/StateManagementLibra.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '../types/EscrowTypes.sol';

/**
 * @title StateManagementLibrary
 * @notice Library for escrow state transitions and event emission
 * @dev Extracted from BaseEscrow to reduce contract size
 */
library StateManagementLibrary {
    /**
     * @dev Transition escrow to RELEASED state
     * @param et EscrowTransfer storage reference
     * @return oldStatus Previous state
     */
    function transitionToReleased(
        EscrowTransfer storage et,
        uint256 /* workflowId */
    ) internal returns (EscrowState oldStatus) {
        oldStatus = et.escrowState;
        et.escrowState = EscrowState.RELEASED;
        return oldStatus;
    }

    /**
     * @dev Transition escrow to REFUNDED state
     * @param et EscrowTransfer storage reference
     * @return oldStatus Previous state
     */
    function transitionToRefunded(
        EscrowTransfer storage et,
        uint256 /* workflowId */
    ) internal returns (EscrowState oldStatus) {
        oldStatus = et.escrowState;
        et.escrowState = EscrowState.REFUNDED;
        return oldStatus;
    }

    /**
     * @dev Transition escrow to RESOLVED state
     * @param et EscrowTransfer storage reference
     * @return oldStatus Previous state
     */
    function transitionToResolved(
        EscrowTransfer storage et,
        uint256 /* workflowId */
    ) internal returns (EscrowState oldStatus) {
        oldStatus = et.escrowState;
        et.escrowState = EscrowState.RESOLVED;
        return oldStatus;
    }

    /**
     * @dev Transition escrow to DISPUTED state
     * @param et EscrowTransfer storage reference
     * @param isSender True if sender is raising dispute, false if recipient
     * @return oldStatus Previous state
     */
    function transitionToDisputed(
        EscrowTransfer storage et,
        uint256 /* workflowId */,
        bool isSender
    ) internal returns (EscrowState oldStatus) {
        oldStatus = et.escrowState;
        et.escrowState = EscrowState.DISPUTED;

        if (isSender) {
            et.senderStatus = SenderStatus.RAISE_DISPUTE;
        } else {
            et.recipientStatus = RecipientStatus.RAISE_DISPUTE;
        }

        return oldStatus;
    }
}

contracts/libraries/YieldHandlingLibrary.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '../interfaces/IYieldGenerationModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
import './ResolverLogicLibrary.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';

/**
 * @title YieldHandlingLibrary
 * @notice Library for yield withdrawal and distribution orchestration
 * @dev Extracted from BaseEscrow to reduce contract size
 *      Handles the workflow: calculate yield → withdraw → distribute
 */
library YieldHandlingLibrary {
    using SafeERC20 for IERC20;
    /**
     * @dev Result of yield withdrawal operation
     */
    struct YieldWithdrawalResult {
        uint256 actualAmount; // Actual amount withdrawn (may include yield)
        uint256 yield; // Yield amount (actualAmount - originalAmount)
        uint256 yieldToDistribute; // Proportional yield to distribute
    }

    /**
     * @dev Withdraw full amount from yield module (for complete release/cancel)
     * @param genModule Yield generation module (can be address(0))
     * @param workflowId Escrow workflow ID
     * @param token Token address
     * @param amount Amount to withdraw
     * @return actualAmount Actual amount withdrawn (may include yield)
     * @return yield Yield amount (actualAmount - amount, if positive)
     */
    function withdrawFullWithYield(
        IYieldGenerationModule genModule,
        uint256 workflowId,
        address token,
        uint256 amount
    ) internal returns (uint256 actualAmount, uint256 yield) {
        actualAmount = amount;
        yield = 0;

        if (address(genModule) == address(0)) {
            return (actualAmount, yield);
        }

        (bool success, uint256 amt, ) = genModule.withdrawWithYield(workflowId, token, amount);

        if (success) {
            actualAmount = amt;
            if (amt > amount) {
                yield = amt - amount;
            }
        }

        return (actualAmount, yield);
    }

    /**
     * @dev Distribute yield via distribution module
     * @param distModule Yield distribution module (must not be address(0))
     * @param workflowId Escrow workflow ID
     * @param token Token address
     * @param yieldAmount Yield amount to distribute
     * @dev Transfers yield to module first, then calls distributeYield
     *      Reverts if distribution fails
     */
    function distributeYield(
        IYieldDistributionModule distModule,
        uint256 workflowId,
        address token,
        uint256 yieldAmount
    ) internal {
        if (yieldAmount == 0) return;
        require(address(distModule) != address(0), 'No yield distribution module');

        // Transfer yield to module first (module expects tokens to be in its balance)
        // This matches the pattern used by DefaultYieldDistributionModule which uses safeTransfer
        IERC20(token).safeTransfer(address(distModule), yieldAmount);

        // Empty distributionData means no distribution configured - yield stays in contract
        // This allows tests to work without full distribution setup
        bytes memory distributionData = '';
        (bool success, ) = distModule.distributeYield(
            workflowId,
            token,
            yieldAmount,
            distributionData
        );
        // Revert if distribution fails - yield should be properly distributed
        // This ensures yield is not lost if distribution module has issues
        require(success, 'Yield distribution failed');
    }

    /**
     * @dev Get approval target from yield generation module
     * @param genModule Yield generation module
     * @param token Token address (for EscrowableERC20, this is address(this))
     * @return approvalTarget Address that needs approval (address(0) if none or handled by module)
     * @dev For EscrowableERC20: module returns pool address, escrow contract handles approval
     *      For EscrowVault: typically returns address(0) as module handles approvals via forceApprove
     */
    function getApprovalTarget(
        IYieldGenerationModule genModule,
        address token
    ) internal view returns (address approvalTarget) {
        if (address(genModule) == address(0)) {
            return address(0);
        }

        // Try to get approval target from module (new interface method)
        try genModule.getApprovalTarget(token) returns (address target) {
            return target;
        } catch {
            // Module doesn't support getApprovalTarget yet, return address(0)
            return address(0);
        }
    }
}

contracts/libraries/YieldPresetLibrary.s.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '../types/YieldPresets.sol';
import '../types/EscrowTypes.sol';

/**
 * @title YieldPresetLibrary
 * @notice Library for deriving yield distribution data from presets
 * @dev Pure functions for deterministic distribution data derivation.
 *      Presets are simple abstractions - distribution data is derived from preset + addresses.
 */
library YieldPresetLibrary {
    /// @notice Error thrown when an invalid preset is used
    error InvalidYieldPreset();

    /**
     * @notice Derive distribution data from preset
     * @param preset The yield preset enum value
     * @param sender The sender address (buyer)
     * @param recipient The recipient address (seller)
     * @return distributionData Encoded (address[] recipients, uint256[] percentages)
     * @dev Returns empty bytes for OFF preset. Returns encoded arrays for enabled presets.
     */
    function deriveDistributionData(
        YieldPreset preset,
        address sender,
        address recipient
    ) internal pure returns (bytes memory distributionData) {
        // Intentionally unused for current presets (kept for forward-compatible preset expansion)
        recipient;

        if (preset == YieldPreset.OFF) {
            return ''; // Empty = no distribution
        }

        if (preset == YieldPreset.TO_SENDER) {
            // Validate sender
            if (sender == address(0)) revert InvalidAddress(ADDR_GENERIC, sender);

            // Deterministic: 100% to sender
            address[] memory recipients = new address[](1);
            uint256[] memory percentages = new uint256[](1);
            recipients[0] = sender;
            percentages[0] = 10000; // 100% in basis points

            return abi.encode(recipients, percentages);
        }

        // Unknown preset
        revert InvalidYieldPreset();
    }

    /**
     * @notice Check if yield is enabled for preset
     * @param preset The yield preset enum value
     * @return enabled True if yield should be enabled
     */
    function isYieldEnabled(YieldPreset preset) internal pure returns (bool enabled) {
        return preset != YieldPreset.OFF;
    }

    /**
     * @notice Validate preset parameters
     * @param preset The yield preset enum value
     * @param sender The sender address
     * @param recipient The recipient address
     * @dev Reverts if preset requires addresses that are invalid
     */
    function validatePresetParams(
        YieldPreset preset,
        address sender,
        address recipient
    ) internal pure {
        // Intentionally unused for current presets (kept for forward-compatible preset expansion)
        recipient;

        if (preset == YieldPreset.TO_SENDER) {
            if (sender == address(0)) revert InvalidAddress(ADDR_GENERIC, sender);
        }
        // OFF preset requires no addresses
        // Future presets (e.g., YIELD_BOTH) can add their validation here
    }
}

contracts/SettlementOps.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import './shared/interfaces/IResolutionModule.sol';
import './types/EscrowTypes.sol';

/**
 * @title SettlementOps
 * @notice External contract for settlement execution operations
 * @dev Extracted from BaseEscrow to reduce contract size
 *
 *      Key design principles:
 *      - Compute → Apply: Returns settlement result, BaseEscrow applies to state
 *      - No callbacks: Does not write to BaseEscrow state
 *      - View-ish: Could be view functions but may query modules
 *
 *      Pattern:
 *      BaseEscrow calls: executeResolution(...) or executePendingSettlement(...)
 *      SettlementOps returns: (shouldExecute, isRelease, appealDeadline, isFinalRound)
 *      BaseEscrow applies: Updates state and executes transfer
 */
contract SettlementOps is AccessControl {
    // ============ Role Constants ============
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    // ============ Custom Errors ============
    error ZeroOwner();
    // PendingSettlement struct (matches BaseEscrow.PendingSettlement)
    // Note: This must match BaseEscrow.PendingSettlement exactly
    struct SettlementPendingSettlement {
        bool exists;
        bool isRelease;
        uint256 appealDeadline;
        bytes32 resolutionHash;
    }
    /**
     * @dev Result of resolution execution computation
     */
    struct ResolutionResult {
        bool shouldExecute; // Whether resolution should execute immediately
        bool isRelease; // True to release, false to cancel
        uint256 appealDeadline; // Appeal deadline timestamp (0 if immediate)
        bool isFinalRound; // Whether this is the final round (no appeal window)
    }

    /**
     * @notice Constructor for SettlementOps
     * @param initialOwner Address that will receive DEFAULT_ADMIN_ROLE (for initial setup only)
     */
    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert ZeroOwner();
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialOwner must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialOwner);
    }

    /**
     * @notice Register an escrow contract (grants it ROLE_ESCROW_CONTRACT)
     * @param escrowContract Address of the escrow contract
     * @dev Only ROLE_TIMELOCK can register escrow contracts (governance-controlled)
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidAddress(ADDR_ESCROW_CONTRACT, escrowContract);
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    /**
     * @notice Action plan for settlement automation
     * @dev Returned by computeNextAction() to guide BaseEscrow._applyActionPlan()
     */
    struct ActionPlan {
        uint8 action; // 0 = none, 1 = release, 2 = cancel, 3 = set pending
        bool isRelease; // If action == 3 (set pending)
        uint256 appealDeadline; // If action == 3
        bytes32 resolutionHash; // If action == 3
        bool needsFinalization; // Whether to call finalizeDispute on resolution module
    }

    /**
     * @notice Compute resolution execution parameters
     * @param resolutionModule Address of the resolution module
     * @param workflowId Escrow workflow ID
     * @param isRelease True to release to recipient, false to cancel/refund to sender
     * @param timeoutConfig Global timeout configuration
     * @return result Resolution execution result
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      BaseEscrow will apply the result after receiving it.
     *      Only authorized escrow contracts can call this function
     */
    function computeResolutionExecution(
        address resolutionModule,
        uint256 workflowId,
        bool isRelease,
        TimeoutConfig memory timeoutConfig
    ) external view onlyRole(ROLE_ESCROW_CONTRACT) returns (ResolutionResult memory result) {
        result.isRelease = isRelease;
        result.shouldExecute = false;
        result.appealDeadline = 0;
        result.isFinalRound = false;

        // Query appeal deadline from resolution module
        // For DecentralizedResolutionModule, this is stored in DisputeMetadata.appealDeadline[currentRound]
        // For other modules, fall back to timeoutConfig.appealWindowDuration
        if (resolutionModule == address(0)) {
            // No resolution module - use global appeal window duration
            result.appealDeadline = block.timestamp + timeoutConfig.appealWindowDuration;
            return result;
        }

        // Validate module is still a valid contract before calling
        if (resolutionModule.code.length == 0) {
            // Module no longer exists - fallback to global appeal window duration
            result.appealDeadline = block.timestamp + timeoutConfig.appealWindowDuration;
            return result;
        }

        // Try to get appeal deadline and current round from module
        // Use staticcall to query view function
        (bool success, bytes memory data) = resolutionModule.staticcall(
            abi.encodeWithSignature('getAppealDeadlineAndRound(uint256)', workflowId)
        );

        if (success && data.length > 0) {
            // Decode return values: (uint256 appealDeadline, uint8 currentRound, bool isFinalRound)
            (result.appealDeadline, , result.isFinalRound) = abi.decode(data, (uint256, uint8, bool));
        } else {
            // Module doesn't support getAppealDeadlineAndRound - fallback to global config
            result.appealDeadline = block.timestamp + timeoutConfig.appealWindowDuration;
        }

        // If final round (MAX_ROUND), execute immediately (no appeal window)
        if (result.isFinalRound || result.appealDeadline == 0) {
            result.shouldExecute = true;
        }

        return result;
    }

    /**
     * @notice Compute pending settlement execution check
     * @param workflowId Escrow workflow ID
     * @param pending Pending settlement data
     * @param escrowState Current escrow state
     * @return canExecute Whether settlement can be executed
     * @return isRelease True if pending release, false if pending cancel
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      Only authorized escrow contracts can call this function
     */
    function computePendingSettlementExecution(
        uint256 workflowId,
        SettlementPendingSettlement memory pending,
        EscrowState escrowState
    ) external view onlyRole(ROLE_ESCROW_CONTRACT) returns (bool canExecute, bool isRelease) {
        // Intentionally unused (kept for interface/telemetry parity with other ops functions)
        workflowId;

        // Verify pending settlement exists
        if (!pending.exists) {
            return (false, false);
        }

        // Verify appeal window has expired
        if (block.timestamp < pending.appealDeadline) {
            return (false, false);
        }

        // Verify state is still DISPUTED (not already executed or escalated)
        if (escrowState != EscrowState.DISPUTED) {
            return (false, false);
        }

        return (true, pending.isRelease);
    }

    /**
     * @notice Compute timed actions (auto-release or auto-cancel)
     * @param et Escrow transfer data
     * @param pending Pending settlement data
     * @return actionType 0 = none, 1 = auto-release, 2 = auto-cancel, 3 = pending settlement
     * @return isRelease True if release action, false if cancel
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      Only authorized escrow contracts can call this function
     */
    function computeTimedActions(
        uint256 /* workflowId */,
        EscrowTransfer memory et,
        SettlementPendingSettlement memory pending,
        TimeoutConfig memory /* timeoutConfig */
    ) external view onlyRole(ROLE_ESCROW_CONTRACT) returns (uint8 actionType, bool isRelease) {
        // Check for pending settlement execution (appeal window enforcement)
        if (
            pending.exists &&
            block.timestamp >= pending.appealDeadline &&
            et.escrowState == EscrowState.DISPUTED
        ) {
            return (3, pending.isRelease);
        }

        // Check for auto-release/auto-cancel (only for PENDING state)
        if (et.escrowState != EscrowState.PENDING) {
            return (0, false);
        }

        if (et.autoReleaseTime > 0 && block.timestamp >= et.autoReleaseTime) {
            return (1, true);
        } else if (et.autoCancelTime > 0 && block.timestamp >= et.autoCancelTime) {
            return (2, false);
        }

        return (0, false);
    }
}

